BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('linux-q19', 'プロセスという考え方',
   'テキストエディタのアプリ（プログラム）を2回起動すると、ウィンドウが2つ開く。この「今動いている実体」を1つずつ何と呼ぶか。',
   NULL::text,
   '["プロセス（起動するたびに新しく作られる、動いている実体）", "プログラム（ディスクに保存された設計図そのもの）", "カーネル（ハードウェアを管理するOSの中核）", "シェル（コマンドを受け付けるプログラム）"]',
   0, '[0]', 'single',
   '{"asked": "起動して今動いている実体を何と呼ぶかを問う問題。", "point": "ディスクの中の「設計図」がプログラム、それを実行してメモリの上で動いている「今の実体」がプロセス。", "kid": "プログラムは料理のレシピ、プロセスは実際にそのレシピで作っている最中の料理。レシピは1冊しかなくても、同時に何品も作れる。", "eg": "たとえるなら、プログラムは「カレーのレシピカード」。プロセスは「今まさにキッチンでカレーを作っている、その鍋の中身」。同じレシピカードから、2つの鍋で同時にカレーを作ることもできる。", "terms": [["プログラム", "ディスクに保存された、実行される前の設計図そのもの"], ["プロセス", "プログラムを実行して、メモリ上で今動いている実体"]], "why_asked": "「プロセスとプログラムは同じもの」という誤解がとても多い。この区別がつかないと、この先のPIDや親子プロセスの話がすべて宙に浮く。", "think": "なぜ区別が要るのかがカギ。もしプログラム＝プロセスなら、同じアプリを2回起動したときに何が2つあるのかを説明できなくなる。実際には「設計図は1つ」のまま「実体だけ2つ」作られている。この「設計図と実体は別物」という考え方が、この先ずっとLinuxの基礎になる。", "vs": "プロセスはプログラムを実行するたびに新しく作られ、終了すれば消える。プログラム（ファイル）自体はディスクに残り続ける点が違う。", "usecase": "自動テストを2つ同時に走らせると、同じテストスクリプト（プログラム）から2つの独立したプロセスが生まれる。片方が固まっても、もう片方には影響しない理由がここにある。", "opt": ["正解。プロセスは、プログラムを実行するたびにメモリ上に新しく作られる「今動いている実体」。", "プログラムはディスクに保存された設計図そのもので、実行前もそこにあり続ける。実行中の実体ではない。", "カーネルはOSの中核で、プロセスの管理役ではあるが、動いているアプリの実体そのものではない。", "シェルはコマンドを受け付けて実行するプログラムの一種で、あらゆる「今動いている実体」を指す言葉ではない。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"30\" width=\"140\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"54\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラム</text><text x=\"90\" y=\"68\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ディスクの中の設計図</text><line x1=\"170\" y1=\"50\" x2=\"210\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"210,50 204,47 204,53\" fill=\"#3b82f6\"/><text x=\"190\" y=\"40\" font-size=\"9\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">実行</text><rect x=\"210\" y=\"20\" width=\"110\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"265\" y=\"44\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセス</text><text x=\"265\" y=\"58\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">メモリ上で今動いてる</text><text x=\"265\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実体</text><text x=\"90\" y=\"100\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じ設計図から</text><text x=\"90\" y=\"113\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">何度実行してもよい</text></svg>"}'),

  ('linux-q20', 'プロセスという考え方',
   'OSの中で同時にたくさんのプロセスが動いていても、Linuxはそれぞれを取り違えずに管理できる。1つ1つのプロセスに割り振られる、重複しない番号を何と呼ぶか。',
   NULL::text,
   '["PID（プロセスID）。プロセスごとに割り振られる重複しない番号", "IPアドレス（ネットワーク上の機器を識別するための住所のこと）", "UID（ユーザーを識別するために使われる番号のこと）", "ポート番号（通信の窓口を識別するために使われる番号のこと）"]',
   0, '[0]', 'single',
   '{"asked": "プロセスを1つずつ識別するために割り振られる番号の名前を問う問題。", "point": "「プロセスの番号札」がPID。動いているプロセスが増えても、この番号で必ず1つに絞り込める。", "kid": "教室の出席番号のようなもの。同姓同名の生徒がいても、出席番号があれば絶対に取り違えない。", "eg": "たとえるなら、宅配便の「伝票番号」。同じ荷物が同時にたくさん配達中でも、伝票番号さえあれば1つの荷物を確実に指せる。", "terms": [["PID", "Process IDの略。直訳は「プロセス・番号」。動いているプロセス1つ1つに割り振られる重複しない番号"]], "why_asked": "「プロセスを止める」「プロセスの状態を見る」といった操作は、すべてPIDを指定して行う。この番号の存在を知らないと、この先のプロセス管理の話が理解できない。", "think": "なぜ番号が要るのかがカギ。同じプログラムを何度も起動すると、名前（プログラム名）だけでは複数のプロセスを区別できない。同じ名前のプロセスが5個あっても、PIDさえ違えば確実に1つだけを名指しできる。だからOSはプロセスを作るたびに、必ず新しい重複しない番号を割り振る。", "vs": "UIDは「誰がそのプロセスを動かしているか（人）」を表す番号で、PIDは「そのプロセス自体（動いている実体）」を表す番号。役割がまったく違う。", "usecase": "自動テストのプロセスが固まって反応しなくなったとき、PIDを調べてそのプロセスだけをピンポイントで終了させる、という場面で使う。", "opt": ["正解。PID（プロセスID）は、動いているプロセス1つ1つに割り振られる重複しない番号。", "IPアドレスはネットワーク上の機器を識別する住所で、1台のコンピュータの中のプロセスを区別する番号ではない。", "UIDはそのプロセスを誰が動かしているか（ユーザー）を表す番号で、プロセス自体を指す番号ではない。", "ポート番号はネットワーク通信の窓口を識別する番号で、プロセスそのものの識別番号ではない。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスA</text><text x=\"200\" y=\"15\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">PID</text><text x=\"140\" y=\"40\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">PID 501</text><rect x=\"30\" y=\"65\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"85\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスB</text><text x=\"140\" y=\"85\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">PID 502</text><rect x=\"30\" y=\"110\" width=\"90\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"124\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスC</text><text x=\"140\" y=\"124\" font-size=\"9\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">PID 503</text><text x=\"250\" y=\"60\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">重複しない</text><text x=\"250\" y=\"73\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">番号札</text></svg>"}'),

  ('linux-q21', 'プロセスという考え方',
   'あるプロセスが新しい別のプロセスを作り出すと、2つのプロセスの間には「作った側」と「作られた側」という関係が生まれる。この関係を何と呼ぶか。',
   NULL::text,
   '["親プロセスと子プロセス（作った側と作られた側の関係）", "ホストとゲスト（仮想化での機器の関係）", "サーバーとクライアント（要求を受ける側と送る側の関係）", "カーネルとユーザー空間（OSの中核と一般プログラムの区別）"]',
   0, '[0]', 'single',
   '{"asked": "プロセスが別のプロセスを作ったときの関係の呼び名を問う問題。", "point": "プロセスを作った側が「親」、作られた側が「子」。この上下関係が、後で出てくるプロセスの終了・監視の土台になる。", "kid": "プロセスは実は勝手に湧いて出てくるのではなく、必ずどこかの既に動いているプロセスが「もう1つ作って」と頼んで生まれる。頼んだ側が親、生まれた側が子。", "eg": "たとえるなら、会社の「部署が新しいチームを立ち上げる」関係。立ち上げた元の部署が親、新しくできたチームが子。子チームがさらに孫チームを作ることもある。", "terms": [["親プロセス", "新しい別のプロセスを作り出した側"], ["子プロセス", "親プロセスによって新しく作られた側"]], "why_asked": "シェルでコマンドを打つたびに、実は「シェルというプロセスが子プロセスを作って実行している」という仕組みが土台にある。ここを知らないと、シェルとコマンドの関係が腹落ちしない。", "think": "なぜこの親子関係が必要かがカギ。Linuxでは、プロセスは何もないところから突然生まれることはなく、必ず既存のプロセスから複製される形で生まれる。だから最初のプロセス（OS起動時にできる1番目のプロセス）を根っことして、すべてのプロセスは親子関係の木構造でつながっている。この構造があるから、「親が終了したら子はどうなるか」のようなルールを一貫して決められる。", "vs": "ホストとゲストは仮想マシンの機器同士の関係で、1台のコンピュータの中のプロセス同士の関係とは階層が違う。", "usecase": "自動テストのスクリプトからブラウザを起動すると、テストスクリプトのプロセスが親、起動されたブラウザのプロセスが子になる。テストが終わったのに子のブラウザだけ残ってしまう、というよくある不具合はこの親子関係を理解していると原因を追いやすい。", "opt": ["正解。プロセスを作った側が親プロセス、作られた側が子プロセスと呼ばれる。", "ホストとゲストは仮想マシンの機器同士の関係で、1台の中のプロセス同士の関係を指す言葉ではない。", "サーバーとクライアントはネットワーク越しに要求をやり取りする関係で、プロセスを作った/作られたという関係とは別物。", "カーネルとユーザー空間はOSの内部構造の区分であり、プロセス同士の親子関係を指す言葉ではない。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"20\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"170\" y=\"40\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">親プロセス</text><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"170\" y1=\"70\" x2=\"80\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"170\" y1=\"70\" x2=\"260\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"80\" y1=\"70\" x2=\"80\" y2=\"85\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"260\" y1=\"70\" x2=\"260\" y2=\"85\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"30\" y=\"85\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"80\" y=\"105\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">子プロセスA</text><rect x=\"210\" y=\"85\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"260\" y=\"105\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">子プロセスB</text><text x=\"170\" y=\"128\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つの親から複数の子が生まれてよい</text></svg>"}'),

  ('linux-q22', 'プロセスという考え方',
   'シェルで新しいコマンドを実行するとき、裏では「今のプロセスをまず複製する」処理と「複製した方の中身を目的のプログラムに入れ替える」処理の2段階が行われている。この2つの処理を順に呼ぶ名前の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["fork（複製する）してからexec（中身を入れ替える）", "exec（入れ替える）してからfork（複製する）", "kill（終了させる）してからfork（複製する）", "fork（複製する）だけで、execという処理は行われない"]',
   0, '[0]', 'single',
   '{"asked": "新しいプロセスを作って別のプログラムを実行するときの、2段階の処理の順番を問う問題。", "point": "「まず自分のコピーを作る（fork）」→「そのコピーの中身を目的のプログラムに入れ替える（exec）」の順。この2段階でしか新しいプログラムは実行されない。", "kid": "シェルは新しいコマンドを実行するとき、いきなり別人に変身するのではなく、まず「自分自身のコピー」を1つ作る。そのコピーの方だけが、頼まれた別のプログラムの中身に丸ごと入れ替わる。元のシェル自身は変身せずそのまま残る。", "eg": "たとえるなら、会社の担当者が別の専門業者に仕事を頼むとき、自分がその業者に変身するのではなく、「自分の代理人（コピー）」を1人立てて、その代理人だけを丸ごと業者の中身に入れ替えるイメージ。元の担当者はデスクに残って、代理人の完了報告を待つ。", "terms": [["fork", "直訳は「分岐」。今のプロセスをそっくり複製してもう1つのプロセスを作る処理"], ["exec", "直訳は「実行する」。プロセスの中身を、指定した別のプログラムにまるごと入れ替える処理"]], "why_asked": "「コマンドを実行する＝シェルがそのまま別のプログラムに変身する」と誤解しやすい。実際にはコピーを作ってから入れ替える2段階であることが、シェルが実行後も残り続ける仕組みの土台になる。", "think": "なぜ「複製してから入れ替える」という回りくどい2段階が必要かがカギ。もしシェル自身がいきなり別のプログラムに変身してしまったら、コマンドが終わった後にシェル自身も一緒に消えてしまい、次のコマンドを打てなくなる。まずコピー（子プロセス）を作っておけば、そのコピーだけが目的のプログラムに入れ替わって実行され、終わればそのコピーだけが消える。元のシェルは複製する前の姿のまま残り続けられる。だからコマンドを実行してもシェルは終了せず、次のコマンドを待ち続けられる。", "vs": "forkは「複製する」だけで、プロセスの中身（実行されるプログラム）はまだ変わらない。execは中身を入れ替えるだけで、新しいプロセスを作るわけではない。この2つは役割がはっきり分かれている。", "usecase": "自動テストのスクリプトから別のコマンドラインツールを呼び出すとき、裏でこのfork＋execが行われている。子プロセスの終了コードだけを見て親プロセス（テストスクリプト）が続きの処理を判断する、という仕組みの理解につながる。", "opt": ["正解。まずforkで自分自身を複製し、複製した方だけがexecで目的のプログラムに入れ替わる。", "execを先に行うと、複製する前のプロセス自身が入れ替わってしまい、元のプロセスが残らなくなってしまう。", "killはプロセスを終了させる操作であり、新しいプログラムを実行する2段階の処理には含まれない。", "execによる中身の入れ替えを行わなければ、複製されたプロセスは親と同じ中身のまま別のプログラムを実行できない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"55\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"60\" y=\"75\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">親プロセス</text><line x1=\"100\" y1=\"60\" x2=\"150\" y2=\"40\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"150,40 144,37 144,43\" fill=\"#3b82f6\"/><text x=\"125\" y=\"45\" font-size=\"10\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">fork</text><rect x=\"150\" y=\"25\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.2\"/><text x=\"190\" y=\"45\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">複製された</text><text x=\"190\" y=\"55\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">子プロセス</text><line x1=\"190\" y1=\"55\" x2=\"190\" y2=\"90\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"190,90 196,87 196,93\" fill=\"#3b82f6\"/><text x=\"210\" y=\"75\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">exec</text><rect x=\"150\" y=\"90\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.2\"/><text x=\"190\" y=\"110\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">別プログラムに</text><text x=\"190\" y=\"120\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">入れ替わる</text></svg>"}'),

  ('linux-q23', 'プロセスという考え方',
   'あるプロセスをターミナルの操作を占有した状態で実行するか、裏で動かしたまま次のコマンドをすぐ打てる状態で実行するかを分ける、プロセスの実行状態の呼び名の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["フォアグラウンドとバックグラウンド", "親プロセスと子プロセス", "カーネル空間とユーザー空間", "実行中と終了済み"]',
   0, '[0]', 'single',
   '{"asked": "ターミナルを占有するか、裏で動かせるかというプロセスの実行状態の呼び名を問う問題。", "point": "操作を占有して結果を待つのがフォアグラウンド、裏で動かしたまま次の操作に移れるのがバックグラウンド。", "kid": "フォアグラウンドは「今それだけに集中していて、他の作業に手が付けられない状態」。バックグラウンドは「裏でやらせておいて、自分は別の作業を続けられる状態」。", "eg": "たとえるなら、洗濯機を回しながら（バックグラウンド）自分は別の家事をする、というのがバックグラウンド実行。逆に、洗濯物を手洗いしていて、終わるまで他の家事に一切手が付けられない状態がフォアグラウンド実行。", "terms": [["フォアグラウンド", "ターミナルの操作を占有し、そのプロセスが終わるまで次のコマンドを打てない実行状態"], ["バックグラウンド", "裏で動かしたまま、すぐに次のコマンドを打てる実行状態"]], "why_asked": "時間のかかる処理をいちいちフォアグラウンドで待っていると作業が止まってしまう。バックグラウンドという選択肢を知らないと、長い処理のたびに手が止まる。", "think": "なぜこの区別が要るのかがカギ。ターミナルは基本的に「今動かしているプロセスの結果を待って、次の入力を受け付ける」という単純な仕組みになっている。時間のかかる処理をそのまま実行すると、終わるまでターミナルが占有されてしまう。バックグラウンドで実行すると、そのプロセスは裏で動き続けたまま、ターミナルの操作権だけがすぐ手元に戻ってくる。", "vs": "親プロセスと子プロセスは「誰が作ったか」という生まれの関係で、フォアグラウンド/バックグラウンドは「今ターミナルを占有しているかどうか」という実行のされ方の違い。まったく別の軸。", "usecase": "自動テストのサーバーをバックグラウンドで立ち上げてから、同じターミナルでテストコマンドを実行する、という場面で日常的に使われる区別。", "opt": ["正解。ターミナルを占有するフォアグラウンドと、裏で動かせるバックグラウンドという実行状態の呼び名。", "親プロセスと子プロセスはプロセスを作った/作られたという生まれの関係で、ターミナルを占有しているかどうかとは別の軸。", "カーネル空間とユーザー空間はOSの内部構造の区分であり、ターミナルの占有状態を表す言葉ではない。", "実行中と終了済みはプロセスが動いているか終わったかを表す状態で、ターミナルを占有しているかどうかとは別の区別。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"140\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"90\" y=\"44\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">フォアグラウンド</text><text x=\"90\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ターミナルを占有し操作を待つ</text><rect x=\"180\" y=\"25\" width=\"140\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"250\" y=\"44\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">バックグラウンド</text><text x=\"250\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">裏で動き続け操作は返る</text><text x=\"90\" y=\"90\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">&amp; を付けて起動</text><line x1=\"90\" y1=\"80\" x2=\"90\" y2=\"68\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"90,68 96,65 96,71\" fill=\"#3b82f6\"/><text x=\"250\" y=\"90\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">すぐ次のコマンドを打てる</text><line x1=\"250\" y1=\"80\" x2=\"250\" y2=\"68\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"250,68 256,65 256,71\" fill=\"#3b82f6\"/></svg>"}'),

  ('linux-q24', 'プロセスという考え方',
   '同じテキストエディタのアプリを3回起動すると、動いているプロセスの数はどうなるか。',
   NULL::text,
   '["3つの独立したプロセスができ、それぞれ別々に動く", "1つのプロセスが3つのウィンドウを内部で共有するだけで、プロセスは1つのまま", "最初に起動した1つ目のプロセスが、2つ目・3つ目の起動要求を吸収してしまう", "同じプログラムなので2回目以降は起動できず、エラーになる"]',
   0, '[0]', 'single',
   '{"asked": "同じプログラムを複数回起動したときにできるプロセスの数を問う問題。", "point": "プログラムは1つでも、実行するたびに独立したプロセスが新しく作られる。プロセスの数と、プログラム（アプリの種類）の数は別物。", "kid": "レシピが1枚しかなくても、その1枚から同時に3つの鍋でカレーを作れるように、同じプログラムからでも起動するたびに別々のプロセスが生まれる。", "eg": "たとえるなら、同じ映画の上映を3つのスクリーンで同時に行っているようなもの。フィルム（プログラム）は共通でも、上映（プロセス）は3つとも別々に進行していて、1つのスクリーンが止まっても他のスクリーンには関係ない。", "terms": [["プロセス", "プログラムを実行するたびに新しく作られる、独立した実行の実体"]], "why_asked": "「同じアプリを2つ開いたら中身は共有されているはず」という誤解がある。実際には完全に独立したプロセスなので、片方が固まってももう片方は無事、という挙動の理由がここにある。", "think": "なぜ独立したプロセスとして分かれるのかがカギ。プロセスはそれぞれ自分専用のメモリ領域を割り当てられて動く。同じプログラムから作られていても、動き出した後は互いのメモリ領域を直接は覗けない独立した存在になる。だから片方のプロセスがフリーズしたりクラッシュしたりしても、もう片方のプロセスの動作には影響しない。", "vs": "「プログラムが1つ＝動いている実体も1つ」という誤解に注意。プログラム（設計図）の数と、プロセス（動いている実体）の数は完全に別の話。", "usecase": "自動テストを複数並列で走らせるとき、同じテストプログラムから複数の独立したプロセスが生まれるからこそ、1つのテストがフリーズしても他のテストは影響を受けずに完走できる。", "opt": ["正解。同じプログラムでも、起動するたびに独立した別々のプロセスが新しく作られる。", "プロセスはそれぞれ独立したメモリ領域を持つ実体で、内部でウィンドウだけ共有するような仕組みにはならない。", "2回目・3回目の起動要求も、それぞれ独立した新しいプロセスとして正常に作られる。1つ目に吸収されることはない。", "同じプログラムは何度でも起動でき、そのたびに新しいプロセスが作られる。2回目以降がエラーになるわけではない。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"20\" width=\"100\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"170\" y=\"37\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラム(1つ)</text><line x1=\"170\" y1=\"45\" x2=\"90\" y2=\"65\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"65\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"170\" y1=\"45\" x2=\"250\" y2=\"65\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"50\" y=\"65\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"90\" y=\"85\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスX</text><rect x=\"130\" y=\"65\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"170\" y=\"85\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスY</text><rect x=\"210\" y=\"65\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"250\" y=\"85\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスZ</text><text x=\"170\" y=\"115\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">3つとも独立して動く。1つが落ちても他は無事</text></svg>"}'),

  ('linux-q25', '標準入出力とパイプ',
   'プログラムが外部とやり取りする「入口」と「出口」は、実は3種類に分けて管理されている。データを受け取る入口、正常な結果を出す出口、不具合や失敗を報告する別の出口の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["標準入力・標準出力・標準エラー出力", "PID・UID・GID", "PATH・HOME・USER", "fork・exec・kill"]',
   0, '[0]', 'single',
   '{"asked": "プログラムの入口と出口の3種類の名前を問う問題。", "point": "「入口が1つ、出口が2つ」。データを受け取る標準入力、正常な結果を出す標準出力、不具合を報告する標準エラー出力の3本立て。", "kid": "料理でいうと、材料を受け取る「入口」が1つ（標準入力）、できた料理を出す「出口」が1つ（標準出力）、そしてもし調理中に問題が起きたら別の窓口で「こんな不具合がありました」と報告する出口（標準エラー出力）がもう1つある。", "eg": "たとえるなら、コールセンターの「注文受付窓口」（標準入力）、「商品の受け渡し窓口」（標準出力）、そして「クレーム・不具合報告窓口」（標準エラー出力）が別々に用意されているイメージ。正常な結果とトラブル報告が同じ窓口で混ざらないようにしている。", "terms": [["標準入力", "プログラムがデータを受け取る入口"], ["標準出力", "プログラムが正常な結果を出す出口"], ["標準エラー出力", "プログラムが不具合やエラーメッセージを出す、正常な出口とは別の出口"]], "why_asked": "この3つを知らないと、後で出てくる「リダイレクト」や「パイプ」が何をつないでいるのかが理解できない。すべてこの3つの入口・出口を土台にしている。", "think": "なぜ出口を2つに分けたのかがカギ。もし正常な結果とエラーメッセージが同じ出口から一緒に出てきたら、結果を他のプログラムに渡すときにエラーメッセージまで一緒に紛れ込んでしまう。出口を分けておけば、正常な結果だけを次のプログラムに渡し、エラーメッセージだけを別に確認する、ということができる。", "vs": "PID・UID・GIDはプロセスやユーザーを識別する番号であり、データの入口・出口を指す言葉ではない。", "usecase": "自動テストの実行結果（標準出力）とエラーログ（標準エラー出力）を別々のファイルに分けて保存する、という場面でこの3種類の区別が直接役に立つ。", "opt": ["正解。データを受け取る標準入力、正常な結果を出す標準出力、不具合を報告する標準エラー出力の3種類。", "PID・UID・GIDはプロセスやユーザーを識別する番号で、データの入口・出口を指す言葉ではない。", "PATH・HOME・USERはコマンドの場所やユーザー情報を表す環境変数の名前で、入口・出口の名前ではない。", "fork・exec・killはプロセスを作る/実行する/終了させる操作の名前で、データの入口・出口を指す言葉ではない。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラム</text><line x1=\"120\" y1=\"35\" x2=\"150\" y2=\"35\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><polygon points=\"150,35 144,32 144,38\" fill=\"#6ab08d\"/><text x=\"190\" y=\"25\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">標準出力</text><text x=\"190\" y=\"38\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(結果)</text><line x1=\"50\" y1=\"90\" x2=\"50\" y2=\"50\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><polygon points=\"50,50 56,47 56,53\" fill=\"#60a5fa\"/><text x=\"50\" y=\"105\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">標準入力</text><text x=\"50\" y=\"118\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(材料)</text><line x1=\"100\" y1=\"60\" x2=\"150\" y2=\"90\" stroke=\"#c47070\" stroke-width=\"1.4\"/><polygon points=\"150,90 144,87 144,93\" fill=\"#c47070\"/><text x=\"210\" y=\"90\" font-size=\"10\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">標準エラー出力</text><text x=\"210\" y=\"103\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(不具合の報告)</text></svg>"}'),

  ('linux-q26', '標準入出力とパイプ',
   'コマンドを実行した結果は普通ターミナルの画面に表示されるが、`>` という記号を使うと、その結果を画面ではなくファイルに書き込ませることができる。この「出力先を画面から別の場所に付け替える」操作を何と呼ぶか。',
   NULL::text,
   '["リダイレクト（出力や入力の行き先を、通常とは別の場所に付け替える操作）", "パイプ（あるコマンドの出力を、別のコマンドの入力に直接つなぐ操作）", "マウント（別の場所にあるファイルシステムを、あるディレクトリの下に接続する操作）", "フォーク（プロセスを複製して2つにする操作）"]',
   0, '[0]', 'single',
   '{"asked": "出力先を画面からファイルなどに付け替える操作の名前を問う問題。", "point": "「行き先の付け替え」がリダイレクト。標準出力の行き先を、画面からファイルへ変えるのが `>` の役割。", "kid": "普段は水道の水（結果）がそのまま流し（画面）に流れているところを、ホースをつなぎ替えて、別のバケツ（ファイル）に水を溜めるようにするイメージ。", "eg": "たとえるなら、いつもは店頭でそのまま渡している商品（結果）を、宅配便で別の場所（ファイル）に送るように配送ルートを変更するようなもの。商品そのものは変わらず、行き先だけが変わる。", "terms": [["リダイレクト", "標準入力・標準出力・標準エラー出力の行き先を、通常とは別の場所に付け替える操作"]], "why_asked": "「>」という記号だけを覚えて、何が起きているか理解していない人が多い。「行き先を付け替えているだけ」という仕組みを知っていれば、応用（エラーだけファイルに残す、など）にも対応できる。", "think": "なぜこの仕組みが便利かがカギ。普段、コマンドの結果は標準出力を通じて画面に表示される。しかし標準出力は「決まった1本の出口」であり、その出口の先を画面からファイルに付け替えることができれば、結果を保存したり、後でゆっくり読んだりできるようになる。この「出口の先だけを付け替える」という発想がリダイレクトの正体。", "vs": "パイプは「あるコマンドの出力を、別のコマンドの入力に直接つなぐ」操作で、リダイレクトは「出力（や入力）の行き先を、ファイルなどに付け替える」操作。つなぐ相手が別のコマンドか、ファイルかという違いがある。", "usecase": "自動テストの実行結果を画面に流すだけでなく `> test-log.txt` のようにファイルへ保存しておけば、後からログを読み返して原因を調査できる。", "opt": ["正解。標準出力などの行き先を、画面から別の場所（ファイルなど）に付け替える操作。", "パイプはコマンド同士を直接つなぐ操作で、行き先をファイルなどに付け替えるリダイレクトとは接続先が異なる。", "マウントは別のファイルシステムをディレクトリに接続する操作で、標準出力の行き先を変える操作ではない。", "フォークはプロセスを複製する操作で、出力の行き先を付け替える操作とは別の概念。"], "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"30\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンド</text><line x1=\"120\" y1=\"45\" x2=\"150\" y2=\"45\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><polygon points=\"150,45 144,42 144,48\" fill=\"#6ab08d\"/><text x=\"160\" y=\"35\" font-size=\"14\" fill=\"#c9a04a\" text-anchor=\"start\" font-weight=\"normal\">&gt;</text><rect x=\"190\" y=\"30\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"245\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ファイル</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">画面ではなくファイルに結果を流す</text><line x1=\"170\" y1=\"100\" x2=\"170\" y2=\"88\" stroke=\"#c9a04a\" stroke-width=\"1.4\"/><polygon points=\"170,88 176,85 176,91\" fill=\"#c9a04a\"/></svg>"}'),

  ('linux-q27', '標準入出力とパイプ',
   'コマンドAとコマンドBの間に `|` という記号を置くと、Aが出した結果が、Bの入力としてそのまま渡される。この仕組みを何と呼ぶか。',
   NULL::text,
   '["あるコマンドの標準出力を、別のコマンドの標準入力へ直接つなぐ仕組み", "出力の行き先を画面からファイルへ付け替える、リダイレクトという仕組み", "プロセスを複製してもう1つ作り出す、フォークという仕組み", "別のファイルシステムをディレクトリへ接続する、マウントという仕組み"]',
   0, '[0]', 'single',
   '{"asked": "コマンド同士の出力と入力を直接つなぐ記号の仕組みの名前を問う問題。", "point": "「Aの出口とBの入口を直結する」のがパイプ。ファイルを経由せずに結果がそのまま次のコマンドへ流れ込む。", "kid": "水道管をそのままつなぐイメージ。Aから出た水が地面にこぼれることなく、そのままBの入り口に流れ込んでいく。", "eg": "たとえるなら、工場のベルトコンベアを2台つなげて、1台目の完成品がそのまま2台目の材料として流れ込むようにするイメージ。一度も床（ファイル）に置かれることなく、そのまま次の工程に渡る。", "terms": [["パイプ", "あるコマンドの標準出力を、別のコマンドの標準入力に直接つなぐ仕組み。記号は | "]], "why_asked": "Unix系OSの根っこにある考え方（小さい部品を組み合わせて大きな仕事をする）を、実際に体験できる仕組みがパイプ。ここを理解すると、この先の「なぜLinuxのコマンドは1つ1つが小さいのか」という話につながる。", "think": "なぜパイプが便利かがカギ。1つのコマンドに全部の機能を詰め込むと、コマンドがどんどん複雑になり、少し違う組み合わせをしたいだけでも作り直しが必要になる。パイプがあれば、「一覧を出すコマンド」と「絞り込むコマンド」のように、それぞれ単機能のコマンドを自由につなぎ変えて、その場で新しい組み合わせの処理を作れる。だから多くのコマンドは1つの仕事しかしないくらいシンプルに作られている。", "vs": "リダイレクトは出力の行き先をファイルなどに付け替える仕組みで、パイプはコマンド同士の出口と入口を直結する仕組み。つなぐ相手がファイルか別コマンドかという違いがある。", "usecase": "自動テストのログをそのまま画面に流さず、パイプで「絞り込むコマンド」につないでエラー行だけを抜き出す、という場面で日常的に使われる。", "opt": ["正解。パイプは、あるコマンドの標準出力を別のコマンドの標準入力に直接つなぐ仕組み。", "リダイレクトは出力の行き先をファイルなどに付け替える仕組みで、コマンド同士を直結する仕組みとは接続先が異なる。", "フォークはプロセスを複製する仕組みで、コマンド同士の出力と入力をつなぐ仕組みとは別の概念。", "マウントはファイルシステムをディレクトリに接続する仕組みで、コマンドの出力と入力をつなぐ仕組みとは異なる。"], "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"40\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"60\" y=\"60\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンドA</text><line x1=\"100\" y1=\"55\" x2=\"150\" y2=\"55\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"150,55 144,52 144,58\" fill=\"#3b82f6\"/><text x=\"125\" y=\"45\" font-size=\"16\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">|</text><rect x=\"150\" y=\"40\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"190\" y=\"60\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンドB</text><text x=\"60\" y=\"90\" font-size=\"8.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">標準出力</text><text x=\"190\" y=\"90\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">標準入力として</text><text x=\"190\" y=\"100\" font-size=\"8.5\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">そのまま受け取る</text></svg>"}'),

  ('linux-q28', '標準入出力とパイプ',
   'コマンドの正常な結果を出す出口（標準出力）とは別に、エラーメッセージ専用の出口（標準エラー出力）がわざわざ用意されている理由として最も適切なものはどれか。',
   NULL::text,
   '["正常な結果とエラーを混ぜずに扱え、結果だけを次に渡し、エラーだけ別に確認できる", "エラーメッセージの方が処理速度が速く、専用の出口を分けて高速化するため", "複数プロセスが同時に動くとき、出口が1つでは足りなくなるのを防ぐため", "画面の表示色をエラー用に赤くするために、OSの機能として出口自体が分かれる"]',
   0, '[0]', 'single',
   '{"asked": "標準エラー出力が標準出力と別の出口として用意されている理由を問う問題。", "point": "「混ぜない」のが目的。正常な結果とエラーを同じ出口にすると、パイプで次に渡すときにエラーまで紛れ込んでしまう。", "kid": "もし普通の商品(結果)とクレーム対応の書類(エラー)を同じ箱に詰めて出荷したら、受け取った次の工程が商品だけを取り出せなくなってしまう。だから最初から別の箱（出口）に分けている。", "eg": "たとえるなら、レストランの「注文の品」と「厨房からのクレーム報告」を、同じお盆に載せて客席に運んだら大変なことになる。だから最初から別々のルートで運ぶようにしている。", "terms": [["標準エラー出力", "不具合やエラーメッセージ専用の出口。標準出力とは別に用意されている"]], "why_asked": "「エラーも普通に画面に表示されるから、標準出力と同じでは」と誤解しやすい。実際には別の出口であることを知らないと、パイプでエラーメッセージまで一緒に流れてしまう不具合の原因がわからない。", "think": "なぜ分ける必要があるのかがカギ。パイプで複数のコマンドをつなぐとき、次のコマンドに渡したいのは基本的に正常な結果だけであることが多い。もし出口が1つしかなければ、エラーメッセージまで一緒に次のコマンドに流れ込んでしまい、正しく処理できなくなる。出口を2つに分けておけば、標準出力だけをパイプでつなぎ、標準エラー出力は画面にそのまま表示させたり、別のファイルに保存したりできる。", "vs": "処理速度や画面の色は標準エラー出力を分けている理由ではない。あくまで「正常な結果と異常な報告を混同させないため」という扱いやすさの理由。", "usecase": "自動テストのコマンドをパイプでつないで結果を集計するとき、標準エラー出力が標準出力と別だからこそ、エラーメッセージに集計処理が邪魔されずに済む。", "opt": ["正解。正常な結果とエラーメッセージを混ぜずに扱えるようにするため、出口を分けている。", "出口を分ける理由は処理速度の高速化ではなく、正常な結果とエラーを混同させないための整理。", "出口が足りなくなることを防ぐための仕組みではなく、あくまで内容を混ぜないための区分。", "画面の表示色を変えるための仕組みではなく、出口そのものが分かれているのは扱いやすさのための設計。"], "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"75\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンド</text><line x1=\"120\" y1=\"35\" x2=\"170\" y2=\"20\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><polygon points=\"170,20 164,17 164,23\" fill=\"#6ab08d\"/><text x=\"230\" y=\"15\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">標準出力(正常)</text><line x1=\"120\" y1=\"45\" x2=\"170\" y2=\"70\" stroke=\"#c47070\" stroke-width=\"1.4\"/><polygon points=\"170,70 164,67 164,73\" fill=\"#c47070\"/><text x=\"230\" y=\"75\" font-size=\"9\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">標準エラー出力(異常)</text><text x=\"75\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">出口を分けておけば</text><text x=\"75\" y=\"103\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">正常な結果だけ次に渡せる</text></svg>"}'),

  ('linux-q29', '標準入出力とパイプ',
   'Linuxの多くのコマンドは「一覧を出すだけ」「文字を検索するだけ」のように、あえて1つの単純な仕事しかしないように作られている。この設計の考え方として最も適切なものはどれか。',
   NULL::text,
   '["小さく単純な部品を、パイプで自由に組み合わせて複雑な仕事をこなす考え方（Unix哲学）", "1つのコマンドに全部の機能を詰め込み、他のコマンドと組み合わせずに完結させる考え方", "コマンドを単純にすることで、初心者が覚える単語の数を減らすことだけを目的にした考え方", "処理速度を優先し、機能を削ることで実行速度だけを上げるための設計"]',
   0, '[0]', 'single',
   '{"asked": "多くのコマンドがあえて単純な仕事しかしないように作られている設計思想を問う問題。", "point": "「単機能の部品を、その場でパイプでつなぎ合わせる」のが狙い。組み合わせの自由度が、多機能な1つのコマンドより高くなる。", "kid": "レゴブロックのようなもの。1つ1つのブロックはただの四角い部品だけど、組み合わせ方は無限にある。もし最初から「お城の形」に固まったブロックだったら、お城しか作れない。", "eg": "たとえるなら、工具箱に「ドライバー」「ペンチ」「ハサミ」という単機能の道具が別々に入っているイメージ。1つの万能ツールにまとめてしまうより、単純な道具を必要な分だけ組み合わせた方が、思いつかなかった使い方にも対応できる。", "terms": [["Unix哲学", "1つのプログラムには1つの仕事だけをさせ、パイプでつないで複雑な処理を組み立てるという設計の考え方"]], "why_asked": "「なぜLinuxのコマンドはこんなに小さい単位に分かれているのか」という疑問への答えがこの考え方。標準入出力・パイプという仕組みは、この設計思想を実現するための土台として存在する。", "think": "なぜ単純な部品の方が優れているのかがカギ。多機能な1つのコマンドは、作った人が想定した使い方しかできない。単機能な部品をパイプで自由に組み合わせられれば、作った人が想定していなかった新しい組み合わせも、使う人がその場で作り出せる。標準入力・出力という共通の「つなぎ口」が全コマンドに用意されているからこそ、この自由な組み合わせが実現できる。", "vs": "「機能を削って速くする」ことが目的ではなく、あくまで「組み合わせの自由度を上げる」ことが目的である点に注意。", "usecase": "自動テストのログから「エラー行だけ絞り込み」「件数を数える」という2つの単機能なコマンドをパイプでつなげば、専用の集計ツールを新しく作らなくても、その場で欲しい結果が得られる。", "opt": ["正解。小さく単純な部品を、パイプで自由に組み合わせて複雑な仕事をこなすという考え方。", "1つのコマンドに全部を詰め込む設計は、この考え方とは逆の方向で、組み合わせの自由度を下げてしまう。", "覚える単語を減らすことだけが目的ではなく、あくまで自由に組み合わせられることが狙い。", "実行速度だけを目的にした設計ではなく、組み合わせの自由度を高めることが主な狙い。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"70\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"55\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">一覧を出す</text><rect x=\"105\" y=\"20\" width=\"70\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"140\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">絞り込む</text><rect x=\"190\" y=\"20\" width=\"70\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"225\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">並び替える</text><line x1=\"90\" y1=\"32\" x2=\"105\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"105,32 99,29 99,35\" fill=\"#3b82f6\"/><line x1=\"175\" y1=\"32\" x2=\"190\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"190,32 184,29 184,35\" fill=\"#3b82f6\"/><text x=\"170\" y=\"65\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つ1つは小さい仕事だけをする</text><text x=\"170\" y=\"80\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">組み合わせ方は使う人が自由に決める</text></svg>"}'),

  ('linux-q30', '標準入出力とパイプ',
   '「ファイルの中身を表示する」「特定の文字を含む行だけ検索する」「行数を数える」という3つの単機能コマンドをパイプでつなぐと、まとめて実現できることとして最も適切なものはどれか。',
   NULL::text,
   '["ファイルの中から特定の文字を含む行だけを抜き出して、その件数を数える", "ファイルの中身を暗号化してから、別のファイルに保存する", "3つのコマンドが同時に並列で実行され、一番早く終わったものだけが使われる", "ファイルを削除してから、同じ名前で空のファイルを作り直す"]',
   0, '[0]', 'single',
   '{"asked": "表示・検索・数えるという3つの単機能コマンドをパイプでつなぐと何が実現できるかを問う問題。", "point": "パイプでつなぐと「表示→絞り込み→集計」の一連の流れが、専用のプログラムを新しく作らずにその場で組み立てられる。", "kid": "表示するコマンドが出した「全部の行」を、検索するコマンドが「探している文字を含む行だけ」に絞り込み、数えるコマンドがその「絞り込んだ行の数」を最後に教えてくれる。バケツリレーのように結果が渡っていく。", "eg": "たとえるなら、大量の書類（ファイルの中身）を、まず全部机に広げ（表示）、その中から赤いハンコが押された書類だけをより分け（検索）、最後にその枚数を数える（数える）、という一連の流れを3人で分担して行うイメージ。", "terms": [["パイプでつなぐ", "前のコマンドの結果を、そのまま次のコマンドの入力として渡していくこと"]], "why_asked": "パイプの威力を実感できる典型例。1つ1つは単純なコマンドでも、つなげることで「検索して件数を数える」という、単体では存在しない機能が実現できることを理解する問題。", "think": "なぜ3つを別々のコマンドのままつなぐだけで実現できるのかがカギ。それぞれのコマンドは「標準入力から受け取り、標準出力に結果を出す」という共通のルールに従って作られている。表示するコマンドが出した結果を、検索するコマンドがそのまま入力として受け取り、絞り込んだ結果をさらに数えるコマンドが受け取る。共通のルールがあるからこそ、作った人同士が事前に打ち合わせをしなくても、後から自由につなぎ合わせられる。", "vs": "暗号化やファイルの削除は、この3つのコマンド（表示・検索・数える）のどれも行っていない機能で、この組み合わせでは実現できない。", "usecase": "自動テストのログファイルから「FAIL」という文字を含む行だけを検索し、その件数を数えれば、失敗したテストの数をその場ですぐ確認できる。", "opt": ["正解。ファイルの中から特定の文字を含む行だけを抜き出して、その件数を数える。", "暗号化や別ファイルへの保存は、表示・検索・数えるという3つのコマンドのどれも行っていない機能。", "パイプは前のコマンドの結果を次に渡す仕組みで、3つが並列で競争して結果を出す仕組みではない。", "ファイルの削除や作り直しは、表示・検索・数えるという3つのコマンドのどれも行っていない操作。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"90\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"65\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cat（表示）</text><line x1=\"115\" y1=\"32\" x2=\"140\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"140,32 134,29 134,35\" fill=\"#3b82f6\"/><rect x=\"140\" y=\"20\" width=\"90\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"185\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">grep（検索）</text><line x1=\"235\" y1=\"32\" x2=\"260\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"260,32 254,29 254,35\" fill=\"#3b82f6\"/><rect x=\"260\" y=\"20\" width=\"60\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"290\" y=\"37\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">wc（数える）</text><text x=\"150\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ファイルの中身を出して</text><text x=\"150\" y=\"84\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">エラーの行だけ残し、件数を数える</text></svg>"}'),

  ('linux-q31', '権限とユーザー',
   'Linuxでは、ファイルごとに「誰が読める・書ける・実行できるか」という権限が細かく決められている。この仕組みがもし無かった場合に起きる問題として最も適切なものはどれか。',
   NULL::text,
   '["同じコンピュータの他の利用者のファイルを、誰でも自由に消したり書き換えたりできてしまう", "コンピュータ全体の動作速度が、すべてのファイルで極端に遅くなってしまうという問題", "ファイルを保存できる最大サイズが、権限のあるファイルより小さくなってしまうという問題", "同じ名前のファイルを2つ以上、同じディレクトリに置けなくなってしまうという問題"]',
   0, '[0]', 'single',
   '{"asked": "ファイルの権限という仕組みが無かった場合に起きる問題を問う問題。", "point": "権限が無いと「誰でも誰のファイルでも触れてしまう」。1台のコンピュータを複数人・複数プロセスで安全に共有できなくなる。", "kid": "もし家に鍵という仕組みがなかったら、誰でも他人の部屋に勝手に入って物を持ち出せてしまう。権限は、ファイルという「部屋」にかける鍵のようなもの。", "eg": "たとえるなら、マンションの各部屋に鍵が無い状態。誰でもどの部屋にも入れてしまい、他人の荷物を勝手に持ち出したり捨てたりできてしまう。権限（鍵）があるから、自分の部屋は自分だけが自由にできる。", "terms": [["権限", "ファイルやディレクトリごとに、誰が読み書き・実行できるかを決める仕組み"]], "why_asked": "「なぜLinuxはいちいち権限を細かく設定させるのか」という理由を理解していないと、権限エラーに出会ったときに「面倒な制限」としか感じられない。本来は安全に共有するための仕組みだと知ることが大事。", "think": "なぜ権限が必要かがカギ。Linuxは元々、1台のコンピュータを複数の利用者が同時に使うことを前提に作られてきた。もし全員が全ファイルを自由に読み書きできてしまったら、誰かの作業中のファイルを別の人がうっかり消したり、意図的に他人のファイルを覗いたりできてしまう。ファイルごとに「誰に何を許すか」を決められる仕組みがあることで、他人のファイルは勝手には触れない、という安全な共有が実現できる。", "vs": "動作速度や保存できる最大サイズ、同名ファイルの扱いは権限の仕組みとは関係ない、別々の話。", "usecase": "CIサーバーの共有環境で、自分が作ったテスト用の設定ファイルを他のプロジェクトの人が誤って上書きできないようにする、という場面で権限の仕組みが実際に効いてくる。", "opt": ["正解。他の利用者のファイルを誰でも自由に消したり書き換えたりできてしまう問題が起きる。", "動作速度の低下は権限の有無とは関係のない話で、この仕組みが無くなっても速度自体は変わらない。", "保存できる最大サイズは権限の設定とは別の要因（ディスクの空き容量など）で決まる。", "同じ名前のファイルを同じ場所に置けるかどうかは、権限ではなくファイルシステムの別のルールで決まる。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"100\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"70\" y=\"50\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自分のファイル</text><text x=\"70\" y=\"65\" font-size=\"8\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">消せる/読める</text><rect x=\"150\" y=\"25\" width=\"170\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"235\" y=\"45\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">他人のファイル</text><text x=\"235\" y=\"60\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">許可がなければ</text><text x=\"235\" y=\"72\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">消せない/読めない</text></svg>"}'),

  ('linux-q32', '権限とユーザー',
   'ファイルの権限を表す `r` `w` `x` という3文字は、それぞれ何を許可するかを表している。この3つの組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["読む（read）・書く（write）・実行する（execute）の3つの許可", "所有者（owner）・グループ（group）・その他（other）の3つの対象", "登録（register）・待機（wait）・終了（exit）の3つのプロセス状態", "受信（receive）・送信（write）・接続（connect）の3つの通信操作"]',
   0, '[0]', 'single',
   '{"asked": "rwxという3文字がそれぞれ何を許可しているかを問う問題。", "point": "rwxは「読む(read)・書く(write)・実行する(execute)」の頭文字。ファイルに対してできる操作の種類を、この3つのスイッチで許可・禁止する。", "kid": "rは「見てもいいよ」のスイッチ、wは「書き換えてもいいよ」のスイッチ、xは「プログラムとして実行していいよ」のスイッチ。この3つのオン/オフの組み合わせで、そのファイルに何ができるかが決まる。", "eg": "たとえるなら、図書館の本に「立ち読みOK（読む）」「書き込みOK（書く）」「その場で朗読OK（実行する）」という3種類の別々の許可シールが貼ってあるイメージ。1冊ごとに、どのシールが貼ってあるかが違う。", "terms": [["r", "read（読む）の頭文字。ファイルの中身を見る許可"], ["w", "write（書く）の頭文字。ファイルの中身を書き換える許可"], ["x", "execute（実行する）の頭文字。ファイルをプログラムとして実行する許可"]], "why_asked": "rwxは権限の話で必ず最初に出てくる基本の3文字。ここを暗記ではなく「何を許可しているか」の意味で理解しておかないと、この先の所有者・グループの話が積み上がらない。", "think": "なぜ3種類に分けているのかがカギ。「見る」「書き換える」「実行する」は、それぞれ別の目的・別のリスクを持つ操作。中身を見られても困らないが書き換えられては困るファイルもあれば、プログラムとして実行されると困るファイルもある。3つを別々のスイッチにしておけば、「読むだけは許可するが書き換えは禁止する」のように、目的に応じて細かく許可を調整できる。", "vs": "所有者・グループ・その他は「誰に対して許可するか」という対象の区分であり、rwxは「何を許可するか」という操作の種類。この2つの軸を組み合わせて権限全体が決まる。", "usecase": "自動テストのスクリプトファイルに実行(x)の許可が付いていないと、コマンドとして実行できずエラーになる。「読めるのに実行できない」という不具合の原因を理解するのに直結する。", "opt": ["正解。読む（read）・書く（write）・実行する（execute）の3つの許可を表す。", "所有者・グループ・その他は「誰に許可するか」という対象の区分で、rwxが表す「何を許可するか」とは別の軸。", "登録・待機・終了はプロセスの状態を表す言葉で、ファイルの権限を表すrwxとは無関係。", "受信・送信・接続はネットワーク通信の操作で、ファイルの読み書き実行を表すrwxとは無関係。"], "viz": "<svg viewBox=\"0 0 340 105\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"50\" y=\"25\" font-size=\"16\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">r</text><text x=\"50\" y=\"45\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">読む</text><text x=\"120\" y=\"25\" font-size=\"16\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">w</text><text x=\"120\" y=\"45\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">書く</text><text x=\"190\" y=\"25\" font-size=\"16\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">x</text><text x=\"190\" y=\"45\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行する</text><line x1=\"30\" y1=\"60\" x2=\"30\" y2=\"90\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"30\" y1=\"90\" x2=\"260\" y2=\"90\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><line x1=\"260\" y1=\"90\" x2=\"260\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"145\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">3つのスイッチの組み合わせ</text></svg>"}'),

  ('linux-q33', '権限とユーザー',
   'ファイルの権限は「誰に対する許可か」という視点でも3種類に分けられている。ファイルを作った本人、同じチームのメンバー、それ以外の全員という3種類の対象の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["所有者（owner）・グループ（group）・その他（other）", "読む（read）・書く（write）・実行する（execute）", "親プロセス・子プロセス・孫プロセス", "標準入力・標準出力・標準エラー出力"]',
   0, '[0]', 'single',
   '{"asked": "権限が「誰に対する許可か」で分けている3種類の対象を問う問題。", "point": "「誰に許可するか」の3区分が所有者・グループ・その他。それぞれに別々のrwx（読む・書く・実行する）を設定できる。", "kid": "所有者はそのファイルを作った本人、グループは同じチームの仲間、その他はそれ以外の全員。この3種類の人たちに、それぞれ別々の「見る・書く・実行する」の許可を出せる。", "eg": "たとえるなら、社内文書に「作成者本人は自由に編集できる」「同じ部署のメンバーは閲覧だけできる」「他部署の人はまったく見られない」というように、3段階で公開範囲を設定するイメージ。", "terms": [["所有者(owner)", "そのファイルを作った、または管理する権限を持つ本人"], ["グループ(group)", "そのファイルに紐づけられた、特定のメンバーの集まり"], ["その他(other)", "所有者でもグループのメンバーでもない、それ以外の全利用者"]], "why_asked": "rwx（何を許可するか）とセットでよく問われる、「誰に許可するか」の区分。この2つの軸（誰に×何を）を組み合わせて権限全体が決まる、という理解が権限の土台になる。", "think": "なぜ3段階に分ける必要があるのかがカギ。もし「自分」と「それ以外の全員」の2種類しかなければ、「同じチームのメンバーにだけは見せたいが、それ以外の人には見せたくない」という細かい調整ができない。グループという中間の区分があることで、チーム単位での共有と、それ以外への非公開を両立できる。", "vs": "rwxは「何を許可するか」という操作の種類、所有者・グループ・その他は「誰に許可するか」という対象の種類。両方の軸を組み合わせて初めて、そのファイルの権限全体が決まる。", "usecase": "チームで共有しているテスト用の設定ファイルを、自分（所有者）は自由に編集できるが、他部署（その他）からは読み取りしかできないようにする、という場面で使われる。", "opt": ["正解。ファイルを作った本人（所有者）、同じチーム（グループ）、それ以外の全員（その他）の3種類の対象。", "読む・書く・実行するは「何を許可するか」という操作の種類で、「誰に許可するか」という対象の区分とは別の軸。", "親プロセス・子プロセス・孫プロセスはプロセスの生まれの関係で、ファイル権限の対象区分ではない。", "標準入力・標準出力・標準エラー出力はデータの入口・出口の名前で、ファイル権限の対象区分ではない。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"65\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">所有者</text><text x=\"65\" y=\"53\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">あなた自身</text><rect x=\"125\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"170\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">グループ</text><text x=\"170\" y=\"53\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じチーム</text><rect x=\"230\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"275\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">その他</text><text x=\"275\" y=\"53\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">それ以外の全員</text><text x=\"170\" y=\"85\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">それぞれに別々のrwxを設定できる</text></svg>"}'),

  ('linux-q34', '権限とユーザー',
   'OSの内部では、ユーザーは「yuu」のような名前ではなく、実は番号で管理されている。この番号を何と呼ぶか。',
   NULL::text,
   '["UID（ユーザーID。OS内部でユーザーを識別する番号）", "PID（プロセスID。プロセスを識別する番号）", "PATH（コマンドを探す場所を示す環境変数）", "ポート番号（ネットワーク通信の窓口を識別する番号）"]',
   0, '[0]', 'single',
   '{"asked": "OS内部でユーザーを識別するために使われる番号の名前を問う問題。", "point": "OSが実際に管理しているのは「名前」ではなく「番号(UID)」。ユーザー名は、その番号に人間が読みやすいように付けたラベルにすぎない。", "kid": "「yuu」という名前は、私たち人間が読みやすいように付けたあだ名のようなもの。OSの中身は、実はその人を「1001」というような番号で管理している。", "eg": "たとえるなら、社員証に「山田太郎」という名前が印刷されていても、会社のシステムの中では「社員番号1001」として管理されているようなもの。名前は人間向けの表示で、実際の管理は番号で行われている。", "terms": [["UID", "User IDの略。直訳は「利用者・番号」。OS内部でユーザーを識別するための番号"]], "why_asked": "「ファイルの所有者＝ユーザー名」だと思っていると、OSが実際には番号(UID)で権限を判定しているという裏側の仕組みが見えなくなる。ユーザー削除後もファイルの所有者情報が番号のまま残る、といった挙動の理由もここにある。", "think": "なぜ名前ではなく番号で管理するのかがカギ。名前は変更されることがある（改名など）が、番号なら一意で変わりにくく、プログラム側でも高速に比較できる。ファイルの所有者情報も、実際にはこのUIDという番号で記録されていて、画面に表示するときだけ対応するユーザー名に変換して見せている。", "vs": "PIDは動いているプロセス自体を識別する番号で、UIDは「そのプロセスを誰が動かしているか（人）」を識別する番号。番号という点は同じだが、指しているものがまったく違う。", "usecase": "CI環境で自動テストを実行するユーザーのUIDと、テスト対象のファイルの所有者UIDが違うと、権限エラーで読み書きできないことがある。この時「名前は合っているのに番号がずれている」という裏側の仕組みを理解していると原因を追いやすい。", "opt": ["正解。UID（ユーザーID）は、OS内部でユーザーを識別するための番号。", "PIDはプロセス自体を識別する番号で、そのプロセスを動かしている人（ユーザー）を識別する番号ではない。", "PATHはコマンドを探す場所を示す環境変数の名前であり、ユーザーを識別する番号ではない。", "ポート番号はネットワーク通信の窓口を識別する番号で、ユーザーを識別する番号ではない。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"80\" y=\"40\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ユーザー名 yuu</text><line x1=\"150\" y1=\"35\" x2=\"190\" y2=\"35\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"190,35 184,32 184,38\" fill=\"#3b82f6\"/><rect x=\"190\" y=\"20\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"250\" y=\"40\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">UID 1001</text><text x=\"150\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">OS内部では名前ではなく</text><text x=\"150\" y=\"84\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">番号で管理している</text></svg>"}'),

  ('linux-q35', '権限とユーザー',
   '普段は一般ユーザーとして作業しつつ、システムの設定変更など特別な操作が必要なときだけ `sudo` というコマンドを付けて実行する。この `sudo` が行っていることとして最も適切なものはどれか。',
   NULL::text,
   '["一時的に管理者（root）の権限を借りて、そのコマンドだけを実行するという仕組み", "そのユーザー自体を永久に管理者（root）へ昇格させてしまうという仕組み", "実行するコマンドの処理速度を上げるための、高速化のオプションという仕組み", "パスワードを他のユーザーと共有できるようにするための、設定という仕組み"]',
   0, '[0]', 'single',
   '{"asked": "sudoコマンドが行っていることを問う問題。", "point": "sudoは「そのコマンド1回だけ、rootの力を借りる」仕組み。ユーザー自体が永久にrootへ変わるわけではない。", "kid": "普段は一般ユーザーとして、自分の持ち物（ファイル）だけを触れる範囲で作業している。でもシステム全体に関わる特別な作業をしたいときだけ、`sudo`を付けて「今回だけ管理者の力を貸してください」とお願いする。", "eg": "たとえるなら、会社の一般社員が、普段は自分のデスク周りしか触れないけれど、特別な倉庫の鍵が必要なときだけ「上司の許可を得て、今回だけ倉庫の鍵を借りる」ようなイメージ。借りた鍵はその作業が終われば返す。", "terms": [["root", "Linuxで最も強い権限を持つ、特別な管理者ユーザー"], ["sudo", "一般ユーザーが、一時的にrootの権限を借りてコマンドを実行するための仕組み"]], "why_asked": "「sudoを付ければ何でも解決する」と、意味を理解せずに使ってしまう人が多い。強い権限を一時的に借りているだけだと理解していないと、なぜ普段はrootを使わない方がよいのかが分からない。", "think": "なぜ「一時的に借りる」形にしているのかがカギ。もし普段からrootとして作業していると、ちょっとした操作ミス（間違ったファイルの削除など）が、本来なら守られているはずの重要なファイルにまで及んでしまう。普段は制限された一般ユーザーとして作業し、本当に必要な瞬間だけrootの力を借りる形にしておけば、うっかりミスの被害範囲を小さく抑えられる。", "vs": "「sudoを使う＝そのユーザーがrootになる」という誤解に注意。sudoはあくまでそのコマンド1回に対してrootの権限を貸すだけで、ユーザー自体がroot自体に置き換わるわけではない。", "usecase": "CIサーバーでパッケージをインストールするコマンドなど、システム全体に影響する操作にだけsudoを使い、テストスクリプト本体は一般ユーザーの権限のまま動かす、という使い分けがされる。", "opt": ["正解。一時的に管理者（root）の権限を借りて、そのコマンドだけを実行する。", "sudoを使ってもユーザー自体は一般ユーザーのままで、永久にrootへ昇格するわけではない。", "sudoは権限を一時的に借りる仕組みであり、処理速度を上げるための機能ではない。", "sudoはパスワードを共有する仕組みではなく、あくまで本人が一時的にroot権限を借りるための仕組み。"], "viz": "<svg viewBox=\"0 0 340 118\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"130\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"85\" y=\"45\" font-size=\"14\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">root</text><text x=\"85\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">何でもできる管理者</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"255\" y=\"45\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">一般ユーザー</text><text x=\"255\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自分の範囲だけ</text><text x=\"155\" y=\"95\" font-size=\"12\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">sudo</text><text x=\"155\" y=\"108\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">一時的にrootの力を借りる</text></svg>"}'),

  ('linux-q36', '権限とユーザー',
   '普段の作業は一般ユーザーとして行い、rootでの作業をできるだけ避けるべきだと言われる理由として最も適切なものはどれか。',
   NULL::text,
   '["操作ミスをしたときに、被害が及ぶ範囲を限定できるから", "一般ユーザーの方がrootよりコマンドの実行速度が速いから", "rootのアカウントは1台のコンピュータに1つしか存在を許されていないから", "一般ユーザーでしか、ファイルを新しく作成することができないから"]',
   0, '[0]', 'single',
   '{"asked": "普段rootを避け、一般ユーザーで作業すべき理由を問う問題。", "point": "rootは「何でもできてしまう」からこそ、ちょっとしたミスの被害範囲も「何でも」に広がってしまう。普段は権限を絞っておくことで、ミスの被害を小さく抑えられる。", "kid": "rootは全部の部屋の鍵を持っている管理人のようなもの。管理人が普段からその鍵束を持ち歩いて作業していると、うっかり間違えて他の部屋のドアまで壊してしまうかもしれない。必要なときだけ鍵を借りる方が安全。", "eg": "たとえるなら、工事現場で「重機の操作免許」を持つ人が、ちょっとした片付け作業までいつも重機で行っていたら、ちょっとした操作ミスでも大きな被害につながる。普段は手作業に留め、本当に重機が必要な作業だけ免許を使う方が安全。", "terms": [["root", "システム全体に対する制限のない、最も強い権限を持つユーザー"], ["一般ユーザー", "自分に許可された範囲のファイルやシステム操作しかできない、制限されたユーザー"]], "why_asked": "「rootの方が何でもできて便利だから、最初からrootで作業すればいい」という考えは危険。この危険性の理由（被害範囲の限定）を理解していないと、なぜsudoという「一時的に借りる」仕組みがわざわざ用意されているのかが腹落ちしない。", "think": "なぜ被害範囲が変わるのかがカギ。一般ユーザーには最初から「触れる範囲」に制限がかかっているので、コマンドを打ち間違えても、その制限の外側（システムの重要なファイルなど）までは影響が及ばない。rootには制限がないので、同じ打ち間違いでもシステム全体に被害が及ぶ可能性がある。だから普段は制限のある一般ユーザーとして作業し、必要なときだけsudoで一時的にrootの力を借りるのが安全とされる。", "vs": "実行速度やアカウント数の制限、ファイル作成の可否は、rootを避ける理由とは関係ない。あくまで「操作ミスの被害範囲」が理由。", "usecase": "自動テストのスクリプトを一般ユーザーの権限で動かしておけば、テストコードにバグがあっても、システム全体に致命的な被害が及ぶリスクを抑えられる。", "opt": ["正解。操作ミスをしたときに、被害が及ぶ範囲を一般ユーザーの制限された範囲内に限定できるから。", "一般ユーザーとrootで、コマンド自体の実行速度に違いはない。速度が理由ではない。", "rootのアカウント自体は1つのコンピュータに1つしか作れない、という制限があるわけではない。", "ファイルの作成は一般ユーザーでも自分の持ち分の範囲内であれば行える。作成できるかどうかが理由ではない。"], "viz": "<svg viewBox=\"0 0 340 90\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"130\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.2\"/><text x=\"85\" y=\"45\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">rootで作業</text><text x=\"85\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ミスの被害が全体に及ぶ</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.2\"/><text x=\"255\" y=\"45\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">一般ユーザーで作業</text><text x=\"255\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ミスの被害が限定される</text></svg>"}'),

  ('linux-q37', '環境変数とPATH',
   'シェルやプログラムがいつでも参照できるように、「PATH」や「HOME」のような名前と値の組み合わせを保持しておく仕組みを何と呼ぶか。',
   NULL::text,
   '["名前と値の組み合わせを保持しておく入れ物で、プロセスに引き継がれる", "プロセスに対する短い合図を送るための、名前付きの入れ物という仕組み", "コマンド同士の出力と入力をつなぐための、名前付きの通り道という仕組み", "ファイルの実体の情報を、名前を付けて管理しておくための番号という仕組み"]',
   0, '[0]', 'single',
   '{"asked": "名前と値の組み合わせを保持し、プログラムから参照できる仕組みの名前を問う問題。", "point": "「名前」と「値」がペアになった入れ物が環境変数。プログラムはこの中身を見ることで、様々な設定を知ることができる。", "kid": "名札の付いた箱のようなもの。「PATH」という名札の箱には「コマンドを探す場所のリスト」が、「HOME」という名札の箱には「自分の家（ホームディレクトリ）の場所」が入っている。", "eg": "たとえるなら、会社の共有掲示板に「今日の合言葉」「集合場所」のように、名前を付けたメモが貼ってあるイメージ。誰でもその名前を見れば、必要な情報をすぐに参照できる。", "terms": [["環境変数", "名前と値の組み合わせを保持しておく仕組み。プロセスからいつでも参照でき、子プロセスにも引き継がれる"]], "why_asked": "この先の「なぜコマンドが名前だけで見つかるのか（PATH）」を理解するための土台。環境変数という仕組みそのものを知らないと、PATHの話がただの暗記になってしまう。", "think": "なぜこの仕組みが必要かがカギ。プログラムが動くたびに「自分の家はどこか」「コマンドはどこを探せばいいか」といった情報を、いちいち人間が教え直すのは大変。環境変数という共通の入れ物に、あらかじめ名前を付けて値を入れておけば、どのプログラムからも同じ名前で同じ情報を参照できる。", "vs": "シグナルはプロセスに送る短い合図（終了してね、など）で、環境変数のような「値を保持しておく入れ物」とは役割がまったく違う。", "usecase": "CI環境ごとに違う設定値（テスト対象のURLなど）を、プログラムのコードを書き換えずに環境変数として渡しておけば、同じテストコードを複数の環境で使い回せる。", "opt": ["正解。環境変数は、名前と値の組み合わせを保持しておく入れ物で、プロセスに引き継がれる。", "シグナルはプロセスに対する短い合図の仕組みで、名前と値を保持しておく入れ物ではない。", "パイプはコマンド同士の出力と入力をつなぐ仕組みで、名前と値を保持しておく仕組みとは別物。", "inodeはファイルの実体の情報を管理する番号で、名前と値を保持しておく環境変数とは別の仕組み。"], "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"25\" width=\"120\" height=\"70\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"45\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">環境変数</text><text x=\"50\" y=\"65\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">PATH</text><text x=\"50\" y=\"80\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">HOME</text><text x=\"180\" y=\"65\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">= /usr/bin:...</text><text x=\"180\" y=\"80\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">= /home/yuu</text><text x=\"90\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">名前と値が対になった入れ物</text></svg>"}'),

  ('linux-q38', '環境変数とPATH',
   'ターミナルで `grep` と名前だけを打つと、そのファイルがコンピュータのどこに保存されているかを指定していないのに、正しく実行される。この仕組みを支えている環境変数はどれか。',
   NULL::text,
   '["PATH（コマンドを探す場所のリストが入った環境変数）", "HOME（自分のホームディレクトリの場所が入った環境変数）", "USER（今ログインしているユーザー名が入った環境変数）", "PID（動いているプロセスの番号が入った環境変数）"]',
   0, '[0]', 'single',
   '{"asked": "コマンドを名前だけで実行できる仕組みを支える環境変数を問う問題。", "point": "PATHには「コマンド（実行ファイル）を探しに行く場所のリスト」が入っている。シェルはこのリストを順番に探して、見つかった実行ファイルを動かしている。", "kid": "シェルは`grep`と打たれると、いきなり「どこにあるか分からない」となるのではなく、あらかじめ渡されている「探す場所のリスト（PATH）」を、順番に1つずつ覗きに行く。見つかったところで、そのファイルを実行する。", "eg": "たとえるなら、忘れ物を探すときに、まず「机の中」、次に「かばんの中」、次に「ロッカーの中」というように、決まった順番の候補地リストを1つずつ確認していくイメージ。最初に見つかった場所のものを使う。", "terms": [["PATH", "コマンド（実行ファイル）を探す場所の一覧が入った環境変数"]], "why_asked": "「名前を打つだけでコマンドが動く」ことを当たり前だと思っていると、コマンドが見つからないエラーに出会ったときに原因を追えない。PATHという仕組みを知っていれば、「探す場所のリストに入っていないだけ」と理解できる。", "think": "なぜ場所を指定しなくても実行できるのかがカギ。本来、プログラムを実行するにはファイルの正確な保存場所（パス）が必要になる。しかしPATHという環境変数に「よく使う実行ファイルが置かれている場所のリスト」を登録しておけば、シェルは名前だけを渡されたときに、そのリストを順番に探しに行き、最初に見つかったファイルを実行してくれる。だから毎回長い場所を打たなくても、名前だけでコマンドが実行できる。", "vs": "HOMEは自分の作業場所（ホームディレクトリ）を示す環境変数で、コマンドを探す場所のリストとは別物。両方とも環境変数だが、中に入っている値の意味が違う。", "usecase": "自作のテスト自動化ツールをどこからでも名前だけで呼び出したいとき、そのツールを置いたディレクトリをPATHに追加しておく、という設定でこの仕組みを直接使う。", "opt": ["正解。PATHには、コマンド（実行ファイル）を探す場所の一覧が入っている。", "HOMEは自分のホームディレクトリの場所を示す環境変数で、コマンドを探す場所のリストとは別物。", "USERは今ログインしているユーザー名を示す環境変数で、コマンドを探す仕組みとは無関係。", "PIDはプロセスの番号を示すものであり、そもそもPATHのような環境変数として一覧に入っているものではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"30\" y=\"25\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">コマンド名 grep</text><line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"55\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"60,55 66,52 66,58\" fill=\"#3b82f6\"/><text x=\"30\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">PATHに書かれた場所を</text><text x=\"30\" y=\"83\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">先頭から順に探しにいく</text><rect x=\"190\" y=\"50\" width=\"120\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"250\" y=\"72\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">/usr/bin/grep</text><text x=\"250\" y=\"86\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">見つかったら実行</text></svg>"}'),

  ('linux-q39', '環境変数とPATH',
   'PATHには複数のディレクトリが順番に並んで登録されている。同じ名前の実行ファイルが、PATHに登録された複数のディレクトリに存在していた場合、どれが実行されるか。',
   NULL::text,
   '["PATHのリストの先頭から探して、最初に見つかったディレクトリの実行ファイル", "PATHのリストの末尾から探して、最後に見つかったディレクトリの実行ファイル", "ファイルサイズが一番小さい実行ファイル", "アルファベット順で一番早いディレクトリ名にある実行ファイル"]',
   0, '[0]', 'single',
   '{"asked": "同名の実行ファイルが複数のディレクトリにあるとき、どれが実行されるかを問う問題。", "point": "PATHは「探す順番のリスト」。先頭から順番に探していき、最初に見つかったものを使う。それより後ろに同名のファイルがあっても無視される。", "kid": "忘れ物を探すときの「机の中→かばんの中→ロッカーの中」という順番のリストで、もし机の中にもかばんの中にも同じ物があったら、先に見つけた「机の中」の方を使う。かばんの中の方は見に行かない。", "eg": "たとえるなら、道案内で「まずA交差点、それでもなければB交差点、それでもなければC交差点で目的地を探す」という順番のルールがあるとき、A交差点で見つかればそこで探索は終わり、BやCは確認されない。", "terms": [["PATH", "コマンドを探すディレクトリが、探す順番で並んだリスト"]], "why_asked": "「同じ名前のコマンドを自作したのに、なぜか元からあるコマンドの方が実行される」という不具合の原因が、まさにこのPATHの探索順にある。この順番の考え方を理解していないと原因が追えない。", "think": "なぜ順番が重要かがカギ。もしPATHの探索に決まった順番がなければ、同じ名前のコマンドが複数見つかったときにどれを実行すればいいか決められなくなる。「先頭から順に探し、最初に見つかったもので確定する」という単純なルールを決めておくことで、常に迷わず1つの実行ファイルに絞り込める。", "vs": "「ファイルサイズが小さい方」「アルファベット順で早い方」のような基準ではなく、あくまで「PATHのリストに書かれた順番」だけで決まる。", "usecase": "CI環境で、自作のテストツールを標準のコマンドより先に実行させたいとき、自作ツールを置いたディレクトリをPATHのリストの先頭に追加しておく、という調整に直結する。", "opt": ["正解。PATHのリストの先頭から探して、最初に見つかったディレクトリの実行ファイルが使われる。", "探索は先頭から行われ、末尾から探すわけではない。順番が逆になっている。", "ファイルサイズの大小は探索の基準ではなく、あくまでPATHに書かれた場所の順番で決まる。", "ディレクトリ名のアルファベット順ではなく、PATHのリストに実際に書かれている並び順で探索される。"], "viz": "<svg viewBox=\"0 0 340 95\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"80\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"60\" y=\"37\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/usr/local/bin</text><line x1=\"100\" y1=\"32\" x2=\"120\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"120,32 114,29 114,35\" fill=\"#3b82f6\"/><rect x=\"120\" y=\"20\" width=\"80\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"160\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/usr/bin</text><line x1=\"200\" y1=\"32\" x2=\"220\" y2=\"32\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"220,32 214,29 214,35\" fill=\"#3b82f6\"/><rect x=\"220\" y=\"20\" width=\"80\" height=\"25\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"260\" y=\"37\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/bin</text><text x=\"140\" y=\"65\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">先頭から順番に探し、最初に見つかった</text><text x=\"140\" y=\"78\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行ファイルが使われる</text></svg>"}'),

  ('linux-q40', '環境変数とPATH',
   'シェルの中で値を保持する仕組みには「シェル変数」と「環境変数」の2種類がある。この2つの決定的な違いとして最も適切なものはどれか。',
   NULL::text,
   '["環境変数は子プロセスに引き継がれるが、シェル変数はそのシェルの中だけで使われる", "シェル変数は数値だけを、環境変数は文字列だけを保存できるという型の違い", "環境変数は再起動すると消え、シェル変数は再起動しても残り続けるという違い", "シェル変数はroot権限が無いと作れず、環境変数は誰でも作れるという違い"]',
   0, '[0]', 'single',
   '{"asked": "シェル変数と環境変数の決定的な違いを問う問題。", "point": "「子プロセスに渡るかどうか」が決め手。環境変数は子プロセスにも引き継がれるが、シェル変数はそのシェルだけの持ち物で終わる。", "kid": "シェル変数は「自分のメモ帳に書いたメモ」で、自分しか見られない。環境変数は「みんなに配る回覧板」で、自分から新しく生まれた子プロセスにもその内容がそのまま伝わる。", "eg": "たとえるなら、社員が自分のデスクのメモ用紙に書いたメモ（シェル変数）は、その社員本人しか見られない。一方、部署全体に配る回覧板（環境変数）に書いた内容は、その部署から新しく生まれるチーム（子プロセス）にもコピーが渡される。", "terms": [["シェル変数", "そのシェルの中だけで使われ、子プロセスには引き継がれない値"], ["環境変数", "子プロセス（そのシェルから起動する別のプログラム）にも引き継がれる値"]], "why_asked": "「変数を設定したのに、起動した別のプログラムからは値が見えない」という不具合の原因の多くが、この違いを知らずにシェル変数のまま使ってしまっていること。両者の違いを知っておくと原因をすぐ特定できる。", "think": "なぜ2種類に分ける必要があるのかがカギ。もしすべての変数が自動的に子プロセスに引き継がれてしまうと、ちょっとした一時的なメモのつもりで作った変数まで、起動するすべてのプログラムに渡ってしまい、余計な情報だらけになる。「このシェルだけで使う一時的な値」と「起動する子プロセスにも渡したい値」を分けておくことで、必要な情報だけを子プロセスに渡せる。", "vs": "データ型（数値か文字列か）や再起動での扱い、権限の有無は、シェル変数と環境変数を分ける本質的な違いではない。あくまで「子プロセスに引き継がれるかどうか」が決め手。", "usecase": "自動テストのスクリプトの中でだけ使う一時的な値はシェル変数のままにし、テスト対象のプログラムに渡したい設定値（接続先URLなど）は環境変数にする、という使い分けが実務で行われる。", "opt": ["正解。環境変数は子プロセスに引き継がれるが、シェル変数はそのシェルの中だけで使われる。", "データ型による使い分けではなく、どちらも文字列などの値を保存できる。", "再起動での挙動はどちらも同じで、これが決定的な違いではない。", "権限の有無で作れるかどうかが分かれるわけではなく、どちらも一般ユーザーの権限で作成できる。"], "viz": "<svg viewBox=\"0 0 340 105\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"38\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">シェル変数</text><text x=\"90\" y=\"50\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのシェルの中だけ</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"255\" y=\"38\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">環境変数</text><text x=\"255\" y=\"50\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">子プロセスにも渡る</text><line x1=\"255\" y1=\"60\" x2=\"255\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><polygon points=\"255,75 261,72 261,78\" fill=\"#60a5fa\"/><text x=\"255\" y=\"90\" font-size=\"8.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">子プロセスへ引き継がれる</text></svg>"}'),

  ('linux-q41', '環境変数とPATH',
   'あるシェルで環境変数を1つ設定してから、そのシェルの中で別のプログラムを起動すると、起動されたプログラム（子プロセス）は、その環境変数をどう扱うか。',
   NULL::text,
   '["設定された環境変数のコピーを引き継いだ状態で起動する", "環境変数は一切引き継がれず、子プロセスは何も設定されていない状態で起動する", "子プロセスが起動した瞬間、親であるシェルの環境変数はすべて消えてしまう", "環境変数は引き継がれるが、値だけが空の状態にリセットされて渡される"]',
   0, '[0]', 'single',
   '{"asked": "環境変数が子プロセスにどう引き継がれるかを問う問題。", "point": "環境変数は「コピーして渡される」。子プロセスは起動した瞬間に、親の環境変数の写しを自分の分として持つ。", "kid": "シェルが子プロセスを起動するとき、自分が持っている環境変数の「コピー」を渡してあげる。子プロセスはそのコピーを、自分専用の持ち物として使い始める。", "eg": "たとえるなら、上司が持っている資料（環境変数）を、部下に仕事を任せるときにコピーして渡すイメージ。部下が自分の手元のコピーに書き込みをしても、上司の元の資料には影響しない。", "terms": [["環境変数の引き継ぎ", "プロセスが子プロセスを起動するとき、自分の環境変数のコピーを渡すこと"]], "why_asked": "「環境変数を設定したのに、起動したプログラムには伝わっていない」という不具合の多くは、この引き継ぎの仕組みを正しく理解していないことが原因。特にシェル変数のまま設定してしまい引き継がれない、というミスにつながる。", "think": "なぜコピーとして渡すのかがカギ。もし親と子が同じ環境変数を共有していたら、子プロセスが環境変数を書き換えたときに、親プロセスの環境まで勝手に変わってしまう。コピーとして渡しておけば、子プロセスがその後どう変更しても、親プロセス側の環境変数には一切影響しない。それぞれが独立して自分の環境変数を持てる。", "vs": "「引き継がれない」「消える」「空にリセットされる」というのは、実際の挙動とは逆。環境変数はきちんと値ごとコピーされて子プロセスに渡る。", "usecase": "CIサーバーの設定でテスト対象のURLを環境変数として設定しておけば、その後起動するどのテストプロセス（子プロセス）にも、同じ設定値がコピーされて渡り、いちいち個別に指定しなくて済む。", "opt": ["正解。設定された環境変数のコピーを引き継いだ状態で子プロセスは起動する。", "環境変数は引き継がれないわけではなく、コピーとして子プロセスにも渡る。", "子プロセスが起動しても、親であるシェル側の環境変数が消えることはない。", "値が空にリセットされるのではなく、設定されていた値そのものがコピーされて渡る。"], "viz": "<svg viewBox=\"0 0 340 90\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"75\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">シェル</text><text x=\"75\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">環境変数を持つ</text><line x1=\"120\" y1=\"35\" x2=\"170\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><polygon points=\"170,35 164,32 164,38\" fill=\"#60a5fa\"/><text x=\"145\" y=\"25\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">起動</text><rect x=\"170\" y=\"20\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"230\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">子プロセス</text><text x=\"230\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じ環境変数を</text><text x=\"230\" y=\"72\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コピーして持つ</text></svg>"}'),

  ('linux-q42', 'ジョブ管理とシグナル',
   '動いているプロセスに対して「終了してほしい」「一時停止してほしい」といった短い合図を送る仕組みを何と呼ぶか。',
   NULL::text,
   '["シグナル（プロセスに送られる短い合図の仕組み）", "パイプ（コマンド同士をつなぐ仕組み）", "環境変数（名前と値を保持しておく入れ物）", "リダイレクト（出力先を付け替える仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "プロセスに終了や一時停止などの短い合図を送る仕組みの名前を問う問題。", "point": "シグナルは「短い合図」。プロセスの中身に直接手を突っ込むのではなく、外から合図だけを送り、受け取ったプロセス側がそれに応じて自分の動きを決める。", "kid": "プロセスに向かって「おーい、そろそろ終わってー」と声をかけるようなもの。声をかけられたプロセス（の中のプログラム）が、その合図を受け取ってどう反応するかを自分で決める。", "eg": "たとえるなら、運動会の「笛の合図」。笛が鳴った（シグナルが送られた）ら、選手たちはそれぞれ「スタートする」「止まる」など、決められた反応をする。笛自体は選手の体を直接動かしているわけではなく、あくまで合図。", "terms": [["シグナル", "動いているプロセスに送られる、終了や一時停止などの短い合図"]], "why_asked": "Ctrl+Cで動いているコマンドを止められる、という体験は誰でもあるが、その裏で「シグナルが送られている」という仕組みを知らないことが多い。ここを理解すると、この先のSIGTERMとSIGKILLの違いが腹落ちする。", "think": "なぜ合図という間接的な仕組みなのかがカギ。もしOSがプロセスの内部に直接介入して強制的に処理を書き換えられるとしたら、プロセスが今どんな作業の途中か分からないまま中断させてしまい、データが壊れる危険がある。合図（シグナル）を送るだけにしておけば、プロセス側が「今のファイル保存だけは終わらせてから終了しよう」のように、自分の都合に合わせて後片付けをしてから反応できる。", "vs": "パイプや環境変数、リダイレクトはデータや設定値をやり取りする仕組みで、シグナルは「合図」だけを送る点が根本的に違う。", "usecase": "自動テストが固まって反応しなくなったとき、そのプロセスにシグナルを送って終了させる、という操作の裏側の仕組みがこれにあたる。", "opt": ["正解。シグナルは、動いているプロセスに送られる終了や一時停止などの短い合図。", "パイプはコマンド同士の出力と入力をつなぐ仕組みで、合図を送る仕組みとは別物。", "環境変数は名前と値を保持しておく入れ物で、合図を送る仕組みとは役割が異なる。", "リダイレクトは出力先を付け替える仕組みで、プロセスに合図を送る仕組みとは別物。"], "viz": "<svg viewBox=\"0 0 340 105\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"30\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"65\" y=\"50\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">シェル</text><line x1=\"110\" y1=\"45\" x2=\"150\" y2=\"45\" stroke=\"#c9a04a\" stroke-width=\"1.4\"/><polygon points=\"150,45 144,42 144,48\" fill=\"#c9a04a\"/><text x=\"130\" y=\"35\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">合図</text><rect x=\"150\" y=\"30\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"210\" y=\"50\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">動いているプロセス</text><text x=\"210\" y=\"80\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">内容を読み取って</text><text x=\"210\" y=\"93\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自分の動きを決める</text></svg>"}'),

  ('linux-q43', 'ジョブ管理とシグナル',
   'ターミナルで動いているコマンドを、キーボードの `Ctrl+C` を押して止めることがある。このとき裏で実際に起きていることとして最も適切なものはどれか。',
   NULL::text,
   '["SIGINTという名前のシグナル（割り込みの合図）がそのプロセスに送られている", "そのプロセスが動いているメモリ領域が、OSによって物理的に消去されている", "キーボードとプロセスの間の電気的な接続が、一時的に切断されている", "PATHという環境変数の中身が、その場で書き換えられている"]',
   0, '[0]', 'single',
   '{"asked": "Ctrl+Cを押したときに裏で起きていることを問う問題。", "point": "Ctrl+Cは「SIGINT」という名前のシグナルをそのプロセスに送っているだけ。プロセス側がその合図を受け取って、自分で中断の処理を行っている。", "kid": "Ctrl+Cを押すと、コンピュータが強制的にプロセスの息の根を止めているわけではなく、「ちょっと中断してね」という合図（SIGINT）を送っているだけ。受け取ったプロセスの方が、その合図に従って自分から中断する。", "eg": "たとえるなら、演奏中の楽団に指揮者が「ストップ」の合図を出すイメージ。指揮者が楽器を物理的に取り上げているわけではなく、合図を受けた演奏者たちが自分で演奏をやめている。", "terms": [["SIGINT", "Signal Interruptの略。直訳は「合図・割り込み」。Ctrl+Cで送られる、処理を中断してほしいという合図"]], "why_asked": "Ctrl+Cは日常的に使う操作だが、「シグナルが送られている」という裏側の仕組みを知らないと、この後に出てくるSIGTERMやSIGKILLとの違いが理解できない。", "think": "なぜ「合図を送る」という間接的な形なのかがカギ。もしCtrl+Cが直接プロセスのメモリを消去する操作だったら、途中まで書きかけていたファイルなどがそのまま壊れて残ってしまう危険がある。SIGINTという合図を送るだけにしておけば、プロセス側が「途中の作業を安全に片付けてから終了する」という反応を自分で選べる。", "vs": "メモリの物理的な消去やキーボードの電気的な切断は起きていない。あくまで「合図が送られ、プロセス側がそれに応じて動く」という間接的な仕組み。", "usecase": "自動テストを手動で途中停止したいとき、Ctrl+Cで送られるSIGINTを受け取ったテストツールが、実行中のテスト結果を後片付けしてから終了する、という挙動の裏側がこれにあたる。", "opt": ["正解。SIGINTという名前のシグナル（割り込みの合図）がそのプロセスに送られている。", "メモリ領域を物理的に消去する操作ではなく、あくまでプロセスに合図を送っているだけ。", "キーボードとプロセスの間の電気的な接続を切る操作ではなく、ソフトウェア上の合図のやり取り。", "PATHという環境変数を書き換える操作ではなく、動いているプロセスに合図を送る操作。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"30\" y=\"30\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">Ctrl</text><text x=\"65\" y=\"30\" font-size=\"13\" fill=\"#8892a4\" text-anchor=\"start\" font-weight=\"normal\">+</text><text x=\"75\" y=\"30\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">C</text><line x1=\"100\" y1=\"25\" x2=\"150\" y2=\"25\" stroke=\"#c9a04a\" stroke-width=\"1.4\"/><polygon points=\"150,25 144,22 144,28\" fill=\"#c9a04a\"/><text x=\"200\" y=\"20\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">SIGINT</text><text x=\"200\" y=\"35\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(割り込みの合図)</text><text x=\"170\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">動いているプロセスに</text><text x=\"170\" y=\"84\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「中断してね」と伝える</text></svg>"}'),

  ('linux-q44', 'ジョブ管理とシグナル',
   'プロセスを終了させるシグナルには「SIGTERM」と「SIGKILL」の2種類がよく使われる。この2つの違いとして最も適切なものはどれか。',
   NULL::text,
   '["SIGTERMは後片付けの猶予を与える終了のお願いだが、SIGKILLは猶予なしの問答無用な強制終了", "SIGTERMはメモリだけ、SIGKILLはディスクのファイルだけを終了させる、という対象の違い", "SIGTERMは一般ユーザーが送れるが、SIGKILLはroot権限がなければ送信できないという違い", "SIGTERMとSIGKILLは名前が違うだけで、プロセスへの効果はまったく同じだという違い"]',
   0, '[0]', 'single',
   '{"asked": "SIGTERMとSIGKILLという2つの終了シグナルの違いを問う問題。", "point": "SIGTERMは「お願いして終了してもらう」、SIGKILLは「有無を言わさず終了させる」。後片付けの猶予があるかどうかが決定的な違い。", "kid": "SIGTERMは「そろそろ店じまいをお願いします」という声かけ。お店（プロセス）はレジを締めて片付けをしてから閉店できる。SIGKILLは「今すぐ電源を落とします」という強制停止。片付けをする時間は一切与えられない。", "eg": "たとえるなら、SIGTERMは「非常口からゆっくり避難してください」というアナウンス（荷物をまとめる余裕がある）。SIGKILLは「今すぐ建物ごと取り壊します」という強制執行（何も持ち出せない）。", "terms": [["SIGTERM", "Signal Terminateの略。直訳は「合図・終了」。プロセスに後片付けの猶予を与えて終了を頼む合図"], ["SIGKILL", "Signal Killの略。直訳は「合図・強制終了」。プロセスに拒否権も猶予も与えず即座に終了させる合図"]], "why_asked": "「プロセスが固まったら、とりあえずSIGKILLで終了させればいい」と思っていると、保存されるはずだったデータが失われるなどの被害につながる。まずSIGTERMを試すべき理由の理解につながる。", "think": "なぜ2種類に分かれているのかがカギ。SIGTERMは合図としてプロセスに届き、受け取ったプログラム自身が「保存してから終了する」といった後片付けの処理を実行してから終了できる。一方SIGKILLはプログラム自身に処理をする隙を与えず、OSが強制的にそのプロセスを止めてしまう合図。だからまずSIGTERMで「お願い」してみて、どうしても反応しないときの最後の手段としてSIGKILLを使う、という順番が推奨される。", "vs": "メモリとディスクを別々に終了させる、という区別ではない。あくまで「後片付けの猶予があるかどうか」がSIGTERMとSIGKILLの違い。", "usecase": "固まった自動テストのプロセスを止めるとき、まずSIGTERMを送って正常に終了する猶予を与え、それでも反応しない場合の最後の手段としてSIGKILLを使う、という判断がここに基づく。", "opt": ["正解。SIGTERMは後片付けの猶予があるお願い、SIGKILLは猶予のない強制終了。", "メモリとディスクを別々に終了させる仕組みではなく、両方ともプロセス全体に対する終了の合図。", "一般ユーザーでもSIGTERM・SIGKILLどちらも、自分が動かしているプロセスに対しては送ることができる。", "2つは効果が同じではなく、後片付けの猶予があるかどうかという決定的な違いがある。"], "viz": "<svg viewBox=\"0 0 340 95\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.2\"/><text x=\"90\" y=\"42\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">SIGTERM</text><text x=\"90\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">お願いベースの終了要求</text><rect x=\"180\" y=\"20\" width=\"140\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.2\"/><text x=\"250\" y=\"42\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">SIGKILL</text><text x=\"250\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">問答無用の強制終了</text><text x=\"90\" y=\"80\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">後片付けできる</text><text x=\"250\" y=\"80\" font-size=\"9\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">後片付けできない</text></svg>"}'),

  ('linux-q45', 'ジョブ管理とシグナル',
   'プロセスを終了させたいとき、なぜ最初からSIGKILLを使うのではなく、まずSIGTERMを試すべきだと言われるのか。最も適切な理由はどれか。',
   NULL::text,
   '["SIGTERMなら安全に片付けて終了でき、SIGKILLは猶予がなくデータが壊れる恐れがある", "SIGKILLはroot権限を持つユーザーにしか送信する権限が与えられていないという違い", "SIGTERMの方がSIGKILLより処理負荷が軽く、常に高速に終了できるという違い", "SIGKILLを送ると、そのプロセスを動かしていたユーザーのアカウントごと削除される"]',
   0, '[0]', 'single',
   '{"asked": "最初からSIGKILLを使わず、まずSIGTERMを試すべき理由を問う問題。", "point": "「安全に終われるかどうか」が理由。SIGTERMなら後片付けの猶予があるが、SIGKILLは問答無用で、作業中のデータが中途半端な状態のまま残る危険がある。", "kid": "急いでいるからといって、いきなり店の電源を落とす（SIGKILL）と、レジの締め作業の途中だったお金の記録がぐちゃぐちゃになってしまうかもしれない。まずは「閉店してください」とお願い（SIGTERM）して、きちんと片付けてから終わってもらう方が安全。", "eg": "たとえるなら、パソコンで書類を保存している途中に、いきなりコンセントを抜く（SIGKILL）と、書類が壊れて開けなくなることがある。「保存が終わったら終了してください」とお願いする（SIGTERM）方が、データを守れる。", "terms": [["SIGTERM", "後片付けの猶予を与えて終了を頼む合図"], ["SIGKILL", "後片付けの猶予を与えず即座に終了させる合図"]], "why_asked": "「反応しないプロセスはとりあえずSIGKILLで消せばいい」という短絡的な対応をしがちだが、その裏でどんなリスクを負っているかを理解していないと、必要以上にSIGKILLを乱用してしまう。", "think": "なぜ猶予の有無がそこまで重要かがカギ。プロセスがファイルへの書き込みなど「途中で中断されると困る作業」をしている最中にSIGKILLで即座に止められると、そのファイルは書きかけの中途半端な状態のまま残ってしまう。SIGTERMであれば、プロセス自身が「今書きかけのファイルを安全な状態にしてから終了する」という後始末を行える。だから、まずSIGTERMで穏便に終了を試み、それでも反応がない場合の最後の手段としてのみSIGKILLを使うべきとされる。", "vs": "権限の違いや処理速度、アカウントの削除は理由ではない。あくまで「データを安全に片付けられるかどうか」が本質的な理由。", "usecase": "自動テストがファイルへの書き込み処理の途中で固まったとき、いきなりSIGKILLで止めるとログファイルが壊れることがある。まずSIGTERMで穏便な終了を試すという判断はここに基づく。", "opt": ["正解。SIGTERMなら安全に片付けてから終了できるが、SIGKILLはその猶予を与えず、データが壊れる恐れがある。", "SIGKILLも一般ユーザーが自分の動かしているプロセスに対して送信できる。root権限が必須というわけではない。", "処理負荷や速度の差が理由ではなく、あくまで安全に終了できるかどうかが理由。", "SIGKILLを送ってもユーザーアカウント自体が削除されることはない。あくまで対象プロセスが終了するだけ。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"90\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.2\"/><text x=\"65\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">SIGTERM</text><text x=\"65\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">まず試す</text><line x1=\"115\" y1=\"55\" x2=\"150\" y2=\"55\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><polygon points=\"150,55 144,52 144,58\" fill=\"#8892a4\"/><text x=\"132\" y=\"45\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">反応なし</text><rect x=\"150\" y=\"25\" width=\"90\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.2\"/><text x=\"195\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">SIGKILL</text><text x=\"195\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">最後の手段</text></svg>"}'),

  ('linux-q46', 'ジョブ管理とシグナル',
   'ターミナルで実行中のコマンドを `Ctrl+Z` で一時停止させると、そのプロセスはメモリからも消えてしまうわけではなく、後から命令で再開できる。この一時停止と再開を含めた、実行中のジョブをどう扱うかという操作全般を何と呼ぶか。',
   NULL::text,
   '["実行中の処理を停止・再開・バックグラウンド化などで扱う仕組み", "出力先をファイルなどに付け替える、リダイレクトという仕組み", "別のファイルシステムをディレクトリに接続する、マウントという仕組み", "プロセスを複製して2つにする、フォークという仕組み"]',
   0, '[0]', 'single',
   '{"asked": "実行中のプロセスを停止・再開などで扱う操作全般の名前を問う問題。", "point": "「今動いている仕事（ジョブ）をどう扱うか」を管理するのがジョブ管理。一時停止・再開・バックグラウンド化はすべてこの仕組みの一部。", "kid": "テレビを一時停止して、後から続きを再生できる一時停止ボタンのようなもの。プロセスも消してしまうのではなく、一旦「止めておいて」、後で「続きから再開して」と扱える。", "eg": "たとえるなら、読んでいる途中の本にしおりを挟んで一旦閉じ（一時停止）、後で同じページから読み再開する（再開）ようなイメージ。本を捨てているわけではない。", "terms": [["ジョブ管理", "実行中の処理を、停止・再開・フォアグラウンド/バックグラウンドの切り替えなどで扱う仕組み"], ["Ctrl+Z", "実行中のプロセスを一時停止させるための操作。SIGTSTPという合図が送られる"]], "why_asked": "「Ctrl+Cで終了させる」ことは知っていても、「Ctrl+Zで一時停止して、後から再開できる」ことを知らない人が多い。終了と一時停止の違いを理解しておくことが実務でも役立つ。", "think": "なぜ「終了」ではなく「一時停止」という選択肢があるのかがカギ。長い時間がかかる処理の途中で、少しだけ他の作業をターミナルで行いたいことがある。プロセスを終了させてしまうと、それまでの処理がすべて失われてしまう。一時停止であれば、処理の状態をそのまま保ったまま操作をシェルに戻し、後で同じ続きから処理を再開できる。", "vs": "Ctrl+C（SIGINT）は基本的にプロセスを終了させる合図で、Ctrl+Z（SIGTSTP）は終了させずに一時停止させる合図。目的も送られるシグナルの種類も違う。", "usecase": "自動テストのログを確認する途中で、実行中の長いビルド処理を一時停止して、他の作業を済ませてから続きを再開する、という場面でジョブ管理が使われる。", "opt": ["正解。ジョブ管理は、実行中の処理を停止・再開・バックグラウンド化などで扱う仕組み。", "リダイレクトは出力先を付け替える仕組みで、実行中のプロセスの停止・再開を扱う仕組みとは別物。", "マウントはファイルシステムを接続する仕組みで、実行中のプロセスの扱いとは無関係。", "フォークはプロセスを複製する仕組みで、実行中のプロセスの一時停止・再開とは別の操作。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"65\" y=\"40\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行中</text><line x1=\"120\" y1=\"35\" x2=\"150\" y2=\"35\" stroke=\"#c9a04a\" stroke-width=\"1.4\"/><polygon points=\"150,35 144,32 144,38\" fill=\"#c9a04a\"/><text x=\"135\" y=\"25\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">Ctrl+Z</text><rect x=\"150\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"195\" y=\"40\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">一時停止中</text><line x1=\"255\" y1=\"35\" x2=\"150\" y2=\"60\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><polygon points=\"150,60 156,57 156,63\" fill=\"#6ab08d\"/><text x=\"280\" y=\"45\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"start\" font-weight=\"normal\">再開</text><rect x=\"20\" y=\"55\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"65\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行中に戻る</text></svg>"}'),

  ('linux-q47', 'コンテナの正体',
   '仮想マシン（VM）は、1台の物理サーバーの中に「ゲストOS」を丸ごと複数個動かして、それぞれ独立した環境を作る。一方コンテナは、物理サーバーのOS（カーネル）を複数のアプリで共有しながら、それぞれを独立しているように見せかける。この違いから言えることとして最も適切なものはどれか。',
   NULL::text,
   '["コンテナはOSを共有する分、VMよりも軽量に多数の環境を作りやすい", "コンテナは物理サーバーを複数台用意しないと1つも動かせない", "VMはOSを共有するので、コンテナよりも軽量に動かせる", "コンテナとVMは、実現している仕組みも達成する目的もまったく同じである"]',
   0, '[0]', 'single',
   '{"asked": "VMとコンテナの仕組みの違いから、何が言えるかを問う問題。", "point": "「OSごと複製するか、OSは共有して見た目だけ分けるか」が最大の違い。コンテナはOSを共有する分、VMより軽く多数動かせる。", "kid": "VMは、1つの建物（物理サーバー）の中に、それぞれ独立した「家（ゲストOS）」を何軒も建てるイメージ。家を1軒建てるにはそれなりの手間と広さがいる。コンテナは、1軒の家（共通のOS）の中に、間仕切り（隔離の仕組み）でいくつも独立した部屋を作るイメージ。家自体は1軒で済むので、部屋（コンテナ）はもっと手軽にたくさん作れる。", "eg": "たとえるなら、VMは「マンションの1棟をまるごと複数棟建てる」ようなもの。コンテナは「1棟のマンションの中に、防音のしっかりした部屋をたくさん作る」ようなもの。後者の方が、同じ土地（物理サーバー）でたくさんの独立した空間を用意できる。", "terms": [["VM(仮想マシン)", "1台の物理サーバーの中に、ゲストOSを丸ごと複数個動かして独立した環境を作る仕組み"], ["コンテナ", "OS（カーネル）を共有しながら、プロセスの見える範囲を分けて独立しているように見せる仕組み"]], "why_asked": "「コンテナ＝軽量なVM」という誤解が非常に多い。実際にはOSを複製するかどうかという根本的な仕組みの違いがあり、それが「なぜコンテナは軽いのか」の理由になっている。", "think": "なぜコンテナの方が軽いのかがカギ。VMは、独立した環境を作るために、OSそのものをまるごと複製して起動する。OS自体の起動や動作にはそれなりの時間とメモリが必要になる。コンテナは、物理サーバーが持つ1つのOS（カーネル）を複数のコンテナで共有し、「見える範囲」だけをそれぞれ別々に見せかける仕組みを使う。OSを複製しない分、起動が速く、同時にたくさん動かしても使うメモリが少なく済む。", "vs": "「コンテナは軽量版のVM」ではなく、「OSを共有するか、複製するか」という根本的な仕組みが違う、別系統の技術だと理解しておく。", "usecase": "自動テストの環境を毎回まっさらな状態で用意したいとき、VMよりも起動が速く軽いコンテナを使えば、テストのたびに素早く環境を作り直せる。", "opt": ["正解。コンテナはOSを共有する分、VMよりも軽量に多数の環境を作りやすい。", "コンテナも1台の物理サーバー（とその上のOS）があれば、複数のコンテナを動かせる。複数台の物理サーバーが必須なわけではない。", "OSを共有せず複製するのはVMの方で、コンテナよりも一般的に起動や動作の負荷が大きくなる。", "OSを複製するか共有するかという根本的な仕組みが異なり、目的は近くても実現の仕方は同じではない。"], "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"15\" width=\"140\" height=\"90\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"30\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">物理サーバー</text><rect x=\"30\" y=\"40\" width=\"55\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"57\" y=\"55\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ゲストOS</text><text x=\"57\" y=\"68\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ</text><rect x=\"95\" y=\"40\" width=\"55\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"122\" y=\"55\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ゲストOS</text><text x=\"122\" y=\"68\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ</text><text x=\"90\" y=\"95\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">VM: OSごと丸ごと2つ</text><rect x=\"190\" y=\"15\" width=\"130\" height=\"90\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"255\" y=\"30\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">物理サーバー</text><rect x=\"200\" y=\"40\" width=\"50\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"225\" y=\"58\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ</text><rect x=\"260\" y=\"40\" width=\"50\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"285\" y=\"58\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ</text><rect x=\"198\" y=\"90\" width=\"110\" height=\"10\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"253\" y=\"98\" font-size=\"7.5\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"normal\">共通のOS(カーネル)を共有</text></svg>"}'),

  ('linux-q48', 'コンテナの正体',
   'コンテナAの中からは、コンテナBで動いているプロセスの一覧を見ることができず、まるで自分専用のコンピュータであるかのように振る舞う。同じOS（カーネル）を共有しているのに、この「見える範囲を分ける」ことを実現している仕組みを何と呼ぶか。',
   NULL::text,
   '["プロセスやファイルなど、見える範囲を区切って分離する仕組み", "CPUやメモリなど、使える資源の量そのものを制限する仕組みのこと", "コマンドを探す場所の一覧が入った、PATHという環境変数のこと", "プロセスに送られる、終了や一時停止を伝えるための短い合図のこと"]',
   0, '[0]', 'single',
   '{"asked": "同じOSを共有していても、コンテナごとに見える範囲を分けている仕組みの名前を問う問題。", "point": "「見える範囲を区切る」のがnamespace。同じOSの中で動いていても、コンテナごとに「自分と自分の中身しか見えない」ように仕切っている。", "kid": "1つの大きな建物（OS）の中に、お互いの様子が見えない仕切り壁（namespace）で部屋を区切っているイメージ。同じ建物の中にいても、隣の部屋で誰が何をしているかは見えない。", "eg": "たとえるなら、同じオフィスビル（OS）の中に入っている複数の会社（コンテナ）が、それぞれパーティションで仕切られていて、他の会社の書類や社員が視界に入らないようになっているイメージ。ビル自体（OSの本体）は1つ。", "terms": [["namespace", "直訳は「名前・空間」。プロセスやファイルなど、見える範囲をコンテナごとに区切って分離する仕組み"]], "why_asked": "「コンテナは中で完全に別のコンピュータが動いている」と誤解しがちだが、実際には1つのOSを共有しながら「見える範囲」だけを分けている。この仕組みの名前と役割を知ることが「コンテナの正体」の核心。", "think": "なぜ見える範囲を分ける必要があるのかがカギ。もし全部のコンテナが同じOSの上ですべてのプロセスを見えたり触れたりできてしまったら、あるコンテナの不具合や誤操作が、他のコンテナにまで簡単に影響してしまう。namespaceによってコンテナごとに「自分のプロセス一覧」「自分のファイルシステム」だけが見えるように区切っておくことで、まるで独立したコンピュータのように振る舞わせつつ、実際にはOSは1つで済んでいる。", "vs": "cgroupは「どれだけの量の資源（CPUやメモリ）を使えるか」を制限する仕組みで、namespaceは「何が見えるか（見える範囲）」を区切る仕組み。役割が違う。両方合わさってコンテナの隔離が実現している。", "usecase": "複数のテスト環境をコンテナで同時に動かしても、namespaceのおかげでコンテナごとのプロセスやファイルが混ざらず、それぞれ独立したテスト結果を得られる。", "opt": ["正解。namespaceは、プロセスやファイルなど、見える範囲をコンテナごとに区切って分離する仕組み。", "cgroupは使える資源の量を制限する仕組みで、見える範囲を区切る仕組みとは役割が異なる。", "PATHはコマンドを探す場所のリストが入った環境変数で、見える範囲を区切る仕組みとは無関係。", "シグナルはプロセスに送られる短い合図の仕組みで、見える範囲を区切る仕組みとは別物。"], "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"300\" height=\"90\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"170\" y=\"35\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つのOS（カーネル）</text><rect x=\"35\" y=\"50\" width=\"120\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"95\" y=\"68\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナA</text><text x=\"95\" y=\"82\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自分のプロセスだけ見える</text><rect x=\"185\" y=\"50\" width=\"120\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"245\" y=\"68\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナB</text><text x=\"245\" y=\"82\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Aのプロセスは見えない</text></svg>"}'),

  ('linux-q49', 'コンテナの正体',
   'あるコンテナが暴走してCPUやメモリを使い尽くし、同じサーバー上の他のコンテナまで巻き込んで遅くしてしまう、という事態を防ぐために、コンテナごとに「使える資源の量そのもの」に上限をかける仕組みを何と呼ぶか。',
   NULL::text,
   '["cgroup（CPUやメモリなど、使える資源の量を制限する仕組み）", "namespace（見える範囲を区切って分離する仕組み）", "PATH（コマンドを探す場所のリストが入った環境変数）", "fork（プロセスを複製する仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "コンテナごとに使える資源の量を制限する仕組みの名前を問う問題。", "point": "「使える量そのものに上限をかける」のがcgroup。見える範囲を分けるnamespaceとは別に、資源の取り分を制限する役割を持つ。", "kid": "何人かでシェアハウスに住んでいて、1人が電気やガスを使いすぎると他の人が困ってしまう。cgroupは「あなたはここまでしか電気を使っていいですよ」と、使える量そのものに上限を決めておく仕組み。", "eg": "たとえるなら、オフィスビルの各テナント（コンテナ）に、契約であらかじめ「使える電力はここまで」と上限を決めておくイメージ。1つのテナントが電力を使い尽くして、ビル全体が停電するのを防げる。", "terms": [["cgroup", "Control Groupの略。直訳は「制御・グループ」。CPUやメモリなど、コンテナごとに使える資源の量を制限する仕組み"]], "why_asked": "「見える範囲を分けているだけで安全」と思っていると、資源の使いすぎによる巻き込み事故を防げない。namespaceと役割の違うcgroupがセットで使われていることを理解する必要がある。", "think": "なぜ見える範囲を分けるだけでは足りないのかがカギ。namespaceで「見える範囲」を分けていても、それだけでは実際に使えるCPUやメモリの量自体には制限がかからない。あるコンテナが処理をたくさん抱えてCPUやメモリを使い尽くしてしまうと、同じ物理的な資源を共有している他のコンテナの分まで奪ってしまい、全体が遅くなる。cgroupで「このコンテナはここまでしか使えない」という上限をあらかじめ決めておくことで、1つのコンテナの暴走が他のコンテナを巻き込むのを防げる。", "vs": "namespaceは「何が見えるか」を区切る仕組みで、cgroupは「どれだけ使えるか」を制限する仕組み。この2つが組み合わさって、初めてコンテナの安全な隔離が成り立つ。", "usecase": "複数の自動テストをコンテナで同時に走らせるとき、cgroupで各コンテナのCPU・メモリの上限を決めておけば、1つの重いテストが他のテストの実行速度を巻き込んで悪化させるのを防げる。", "opt": ["正解。cgroupは、CPUやメモリなど、コンテナごとに使える資源の量を制限する仕組み。", "namespaceは見える範囲を区切って分離する仕組みで、使える資源の量そのものを制限する仕組みではない。", "PATHはコマンドを探す場所のリストが入った環境変数で、資源の使用量を制限する仕組みとは無関係。", "forkはプロセスを複製する仕組みで、資源の使用量を制限する仕組みとは別物。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"80\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"35\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナA</text><rect x=\"30\" y=\"45\" width=\"120\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.2\"/><text x=\"90\" y=\"65\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">CPU上限50%</text><text x=\"90\" y=\"80\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">メモリ上限1GB</text><rect x=\"180\" y=\"20\" width=\"140\" height=\"80\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"250\" y=\"35\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナB</text><rect x=\"190\" y=\"45\" width=\"120\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"250\" y=\"65\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">CPU上限30%</text><text x=\"250\" y=\"80\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">メモリ上限512MB</text></svg>"}'),

  ('linux-q50', 'コンテナの正体',
   'コンテナを扱うとき「イメージ」と「コンテナ」という2つの言葉が出てくる。この2つの違いとして最も適切なものはどれか。',
   NULL::text,
   '["イメージは保存された設計図で、コンテナはそのイメージから起動して動いている実体", "イメージとコンテナは同じものを指す別名で、内容にまったく違いはないという説明", "設計図と実体の関係が逆で、動いている実体がイメージ、保存された設計図がコンテナ", "イメージはネットワークの設定情報だけ、コンテナはCPUの設定情報だけを表すという説明"]',
   0, '[0]', 'single',
   '{"asked": "「イメージ」と「コンテナ」という2つの言葉の違いを問う問題。", "point": "「設計図か、動いている実体か」がイメージとコンテナの関係。これはこのドリルの最初に出てきた「プログラムとプロセス」の関係とまったく同じ構図。", "kid": "イメージは、コンテナの中身（アプリやその動作環境）を丸ごと保存した設計図。コンテナは、そのイメージを実際に起動して、今動いている状態のもの。", "eg": "たとえるなら、イメージは「お弁当のレシピと材料一式がセットになった箱」。コンテナは、その箱を開けて実際に調理して、今できあがって食べられる状態のお弁当。同じ箱（イメージ）から何個でも同じお弁当（コンテナ）を作れる。", "terms": [["イメージ", "コンテナの中身（アプリと動作環境）を丸ごと保存した設計図"], ["コンテナ", "イメージから起動して、実際に動いている実体"]], "why_asked": "最初のカテゴリで学んだ「プログラムとプロセス」の関係が、コンテナの世界でも「イメージとコンテナ」という形でそのまま出てくる。同じ考え方の繰り返しだと気づけるかを問う。", "think": "なぜこの2つを分けているのかがカギ。もし設計図と実体が同じものだったら、同じ環境を複数個同時に立ち上げることができなくなる。イメージという「変更されない設計図」を1つ用意しておけば、そこから何個でも独立したコンテナ（実体）を起動できる。これはプログラムから複数のプロセスが生まれる仕組みと、まったく同じ考え方の繰り返し。", "vs": "「プログラムとプロセス」の関係を思い出すと理解しやすい。イメージ＝プログラム（設計図）、コンテナ＝プロセス（動いている実体）という対応関係になっている。", "usecase": "同じテスト環境のイメージを1つ用意しておけば、テストのたびにそのイメージから新しいコンテナを起動して、毎回まっさらな環境でテストを実行できる。", "opt": ["正解。イメージは保存された設計図で、コンテナはそのイメージから起動して動いている実体。", "イメージとコンテナは役割が異なる別の概念であり、同じものを指す別名ではない。", "設計図と実体の関係が逆になっている。動いている実体がコンテナで、保存された設計図がイメージ。", "イメージにはネットワークやCPUの設定だけでなく、アプリ本体や動作環境全体が含まれる。"], "viz": "<svg viewBox=\"0 0 340 90\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"120\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"80\" y=\"50\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">イメージ</text><text x=\"80\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">保存された設計図</text><line x1=\"150\" y1=\"50\" x2=\"190\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><polygon points=\"190,50 184,47 184,53\" fill=\"#3b82f6\"/><text x=\"170\" y=\"40\" font-size=\"9\" fill=\"#3b82f6\" text-anchor=\"middle\" font-weight=\"normal\">起動</text><rect x=\"190\" y=\"25\" width=\"130\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"255\" y=\"50\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ</text><text x=\"255\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">動いている実体</text></svg>"}'),

  ('linux-q51', 'コンテナの正体',
   'コンテナはVMに比べて起動が速く、同時にたくさん動かしても使うメモリが少ないと言われる。この理由として最も適切なものはどれか。',
   NULL::text,
   '["共有するOSの上でプロセスを1つ起動するだけで済み、OSを起動し直さなくてよいから", "コンテナはハードディスクではなく、特別な高速部品の上でしか動かないという決まりがあるから", "コンテナの中では、そもそもプログラムを1行も実行していないという仕組みだから", "コンテナはネットワークに接続しない設計になっており、通信の待ち時間が発生しないから"]',
   0, '[0]', 'single',
   '{"asked": "コンテナがVMより起動が速く、メモリ消費が少ない理由を問う問題。", "point": "「OSを起動し直す必要がないから」が理由。コンテナはOSを共有し、プロセスを1つ起動するだけで済むので、OSごと起動するVMよりずっと軽い。", "kid": "VMは新しい環境を1つ作るたびに「家をまるごと1軒建てる」ような作業（OSの起動）が必要になる。コンテナは、すでに建っている家（共有のOS）の中に「新しい住人を1人迎え入れる」（プロセスを1つ起動する）だけで済む。", "eg": "たとえるなら、VMは新しいお店を出すたびに「建物をまるごと新築する」ようなもの。コンテナは、すでにある建物（OS）の中に「新しいテナントを1つ入居させる」だけ。後者の方が圧倒的に早く準備できる。", "terms": [["起動の重さ", "OSを丸ごと起動するVMは時間もメモリも多く必要で、プロセス1つを起動するだけのコンテナは軽くて済む"]], "why_asked": "「コンテナが軽い」という結果だけを暗記していると、その理由を説明できない。ここまで学んだ「OSを共有するnamespace/cgroupの仕組み」と直接つながる、この章全体のまとめの問題。", "think": "なぜOSを起動し直さなくてよいと軽くなるのかがカギ。OS自体の起動には、ハードウェアの初期化やさまざまな仕組みの立ち上げなど、それなりの時間とメモリが必要になる。コンテナはすでに動いているOS（カーネル）を複数のコンテナで共有し、namespaceで見える範囲を仕切り、cgroupで使える量を制限するだけで独立した環境に見せかけている。OSそのものを起動し直す必要がないので、コンテナの起動は「プロセスを1つ立ち上げる」だけの軽さで済む。", "vs": "特別なハードウェアの上でしか動かない、という決まりはない。コンテナが軽い理由は、あくまでOSを共有し起動し直さずに済むという仕組みにある。", "usecase": "自動テストのたびに毎回まっさらな環境を用意したいとき、VMより起動が速いコンテナなら、テストの実行時間全体を大きく縮められる。", "opt": ["正解。コンテナは共有しているOSの上でプロセスを1つ起動するだけで済み、OS自体を起動し直す必要がないから。", "特別な高速部品の上でしか動かないという決まりはなく、通常のハードディスクやメモリの上でも動く。", "コンテナの中でも通常のプログラムが実行されており、何も実行していないわけではない。", "コンテナもネットワークに接続でき、通信を行わないという設計上の決まりはない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"70\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"35\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">VM(3個)</text><rect x=\"30\" y=\"45\" width=\"35\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"47\" y=\"65\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS</text><rect x=\"75\" y=\"45\" width=\"35\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"92\" y=\"65\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS</text><rect x=\"120\" y=\"45\" width=\"35\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"137\" y=\"65\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS</text><text x=\"90\" y=\"95\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">起動のたびにOSも起動</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"70\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"255\" y=\"35\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ(3個)</text><rect x=\"200\" y=\"50\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.2\"/><text x=\"255\" y=\"65\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OSは共有・使い回し</text><text x=\"255\" y=\"95\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">プロセスの起動だけで済む</text></svg>"}'),

  ('linux-q52', 'ネットワークの基礎',
   'ネットワーク上で通信するとき、「どのコンピュータ宛てか」を表す情報と「そのコンピュータの中のどの窓口（どのプログラム）宛てか」を表す情報は分かれている。この2つの組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["IPアドレスはどのコンピュータか、ポート番号はその中のどの窓口かを表す", "UIDはどのユーザーか、GIDはどのグループかを表す番号の組み合わせ", "PIDはどのプロセスか、PPIDはその親は何かを表す番号の組み合わせ", "所有者は誰のファイルか、パーミッションは何を許可するかを表す情報"]',
   0, '[0]', 'single',
   '{"asked": "通信の宛先を「どのコンピュータか」と「どの窓口か」に分けて表す情報の組み合わせを問う問題。", "point": "IPアドレスは「建物の住所」、ポート番号は「その建物の中の部屋番号」。この2つを組み合わせて初めて、通信の届け先がぴったり決まる。", "kid": "手紙を送るとき、「どの建物に届けるか（住所＝IPアドレス）」と「その建物の中の何号室に届けるか（部屋番号＝ポート番号）」の両方が必要なのと同じ。住所だけでは、建物の中の誰に届ければいいか分からない。", "eg": "たとえるなら、大きなオフィスビル（コンピュータ）に手紙を送るとき、「ビルの住所（IPアドレス）」だけでなく「何階の何号室（ポート番号）」まで書かないと、担当者（プログラム）に届かない。", "terms": [["IPアドレス", "ネットワーク上で、どのコンピュータかを表す住所のような情報"], ["ポート番号", "そのコンピュータの中の、どの窓口（どのプログラム）宛てかを表す番号"]], "why_asked": "「IPアドレスさえ分かれば通信できる」と誤解しやすいが、実際にはそのコンピュータの中で複数のプログラムが同時に通信の窓口を開いていることがあり、ポート番号がないとどの窓口宛てか決められない。", "think": "なぜ2つの情報が必要かがカギ。1台のコンピュータの中では、Webサーバーやメールサーバーなど、複数のプログラムが同時に通信を待ち受けていることがある。IPアドレスだけでは「どのコンピュータか」までしか特定できず、「その中のどのプログラム宛てか」までは決められない。ポート番号という番号を組み合わせることで、初めて「このコンピュータの、この窓口（プログラム）宛て」という届け先が正確に決まる。", "vs": "UID/GIDはユーザーやグループを識別する番号、PID/PPIDはプロセスの識別番号で、どちらもネットワークの宛先を表す情報とは無関係。", "usecase": "自動テストでWebアプリの動作確認をするとき、「localhost:3000」のようにIPアドレス相当の部分とポート番号をセットで指定するのは、まさにこの仕組みを直接使っている。", "opt": ["正解。IPアドレス（どのコンピュータか）とポート番号（そのコンピュータの中のどの窓口か）の組み合わせ。", "UIDとGIDはユーザーやグループを識別する番号で、ネットワーク上の通信の宛先を表す情報ではない。", "PIDとPPIDはプロセスの識別番号で、ネットワーク上の通信の宛先を表す情報ではない。", "所有者とパーミッションはファイルの権限に関する情報で、ネットワーク上の通信の宛先を表す情報ではない。"], "viz": "<svg viewBox=\"0 0 340 95\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"30\" width=\"140\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"90\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">IPアドレス</text><text x=\"90\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">どのコンピュータか</text><rect x=\"180\" y=\"30\" width=\"140\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"250\" y=\"50\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ポート番号</text><text x=\"250\" y=\"65\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのコンピュータの</text><text x=\"250\" y=\"77\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">どの窓口か</text></svg>"}'),

  ('linux-q53', 'ネットワークの基礎',
   'Webサーバーのプログラム（プロセス）が「ポート8080番で通信を待ち受ける」という状態になっているとき、そのプロセスとポート番号を結びつけている仕組みを何と呼ぶか。',
   NULL::text,
   '["プロセスが特定のポート番号で通信を送受信するために開く窓口のこと", "ファイルの実体の情報を管理するために割り振られる、inodeという番号のこと", "プロセスに送られる、終了や一時停止を伝えるための短い合図のこと", "CPUやメモリなど、使える資源の量そのものを制限するための仕組みのこと"]',
   0, '[0]', 'single',
   '{"asked": "プロセスと特定のポート番号を結びつけている仕組みの名前を問う問題。", "point": "「プロセスが開く通信専用の窓口」がソケット。あるポート番号でプロセスが通信を待ち受けている、という状態はこのソケットを通じて実現している。", "kid": "プロセスが「ここで注文（通信）を受け付けます」と、専用の受付窓口を1つ開くイメージ。この受付窓口がソケットで、「8080番の窓口」のように、特定のポート番号に紐づけて開かれる。", "eg": "たとえるなら、コールセンターがビル（コンピュータ）の中に「8080番窓口」という専用の受付カウンター（ソケット）を設置し、そこに常駐する担当者（プロセス）が電話（通信）を待ち受けているイメージ。", "terms": [["ソケット", "プロセスが特定のポート番号で通信を送受信するために開く、通信専用の窓口"]], "why_asked": "「ポート番号を使っている」という状態が、具体的にプロセスの中でどう実現されているのかを知らないと、「ポートが使用中でエラーになる」という不具合の裏側が理解できない。", "think": "なぜソケットという仕組みが必要かがカギ。プロセスがネットワーク越しにデータをやり取りするには、まず「このポート番号で通信を受け付けます」という専用の窓口を開いておく必要がある。この窓口がソケットで、一度開いておけば、外部から届いた通信をそのポート番号宛てに正しく届けられる。ソケットが開かれていなければ、そのポート番号宛てに届いた通信を受け取るプログラムが存在しないことになる。", "vs": "inodeはファイルの実体の情報を管理する番号で、ソケットは通信のための窓口。どちらもLinuxの内部的な仕組みだが、扱っている対象がファイルか通信かという違いがある。", "usecase": "自動テストで「ポート3000番が既に使用中です」というエラーが出たとき、それは別のプロセスがすでにそのポート番号でソケットを開いている状態だと理解できる。", "opt": ["正解。ソケットは、プロセスが特定のポート番号で通信を送受信するために開く窓口。", "inodeはファイルの実体の情報を管理する番号で、ポート番号との結びつきを表す仕組みではない。", "シグナルはプロセスに送られる短い合図の仕組みで、通信の窓口を表す仕組みではない。", "cgroupは使える資源の量を制限する仕組みで、ポート番号との結びつきを表す仕組みではない。"], "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"65\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセス</text><line x1=\"110\" y1=\"35\" x2=\"150\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><polygon points=\"150,35 144,32 144,38\" fill=\"#60a5fa\"/><text x=\"130\" y=\"25\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">開く</text><rect x=\"150\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"195\" y=\"40\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ソケット</text><line x1=\"240\" y1=\"35\" x2=\"280\" y2=\"35\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><polygon points=\"280,35 274,32 274,38\" fill=\"#6ab08d\"/><text x=\"260\" y=\"25\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">待受</text><text x=\"90\" y=\"70\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">ポート8080</text><text x=\"90\" y=\"85\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">を担当する窓口</text></svg>"}'),

  ('linux-q54', 'ネットワークの基礎',
   '自分自身のコンピュータの中で動いているWebサーバーに、同じコンピュータの中からアクセスするとき「localhost」というアドレスがよく使われる。この「localhost」が指しているものとして最も適切なものはどれか。',
   NULL::text,
   '["自分自身のコンピュータを指す、ネットワークの外に出ない特別なアドレス", "インターネット上のどこかにある、決まったサーバー会社のコンピュータ", "同じ社内ネットワークにつながっている、隣の席の同僚のコンピュータ", "まだIPアドレスが割り当てられていない、空っぽの通信窓口のこと"]',
   0, '[0]', 'single',
   '{"asked": "localhostというアドレスが指しているものを問う問題。", "point": "localhostは「自分自身」を指す特別なアドレス。ネットワークの外に一切出ることなく、自分のコンピュータの中だけで通信が完結する。", "kid": "自分で自分に手紙を出すようなもの。ポストに投函しても実際には郵便局を経由せず、自分の家の中で完結して自分の手元に届く。localhostは、そんな「自分自身宛て」の特別な住所。", "eg": "たとえるなら、社内の内線電話で「自分のデスクの電話に自分でかける」ようなもの。外の電話回線には一切出ていかず、内部だけで完結する。", "terms": [["localhost", "自分自身のコンピュータを指す特別なアドレス。実際のIPアドレスでは127.0.0.1にあたる"]], "why_asked": "開発中のアプリを自分のコンピュータの中だけで動作確認する場面で必ず登場する言葉。「外部のサーバーに接続している」という誤解をしていると、意味が分からないまま使い続けてしまう。", "think": "なぜ自分自身を指す特別なアドレスが用意されているのかがカギ。開発中のアプリを試すときに、いちいちインターネット上の本物のサーバーに公開しなくても、自分のコンピュータの中でサーバーとクライアントの役目を両方演じて動作確認したいことがある。localhostという「自分自身に向けた通信」専用のアドレスがあることで、外部のネットワークに一切データを出さずに、自分のコンピュータの中だけで安全に試すことができる。", "vs": "「同じ社内ネットワークの別のコンピュータ」ではなく、あくまで「自分自身」を指す点が違う。隣の席の同僚のコンピュータにアクセスするには、その同僚のコンピュータ自身のIPアドレスが必要になる。", "usecase": "自動テストで、開発中のWebアプリをまだインターネットに公開せず、自分のコンピュータの中だけでlocalhostを使って動作確認する、という場面で日常的に使われる。", "opt": ["正解。localhostは自分自身のコンピュータを指す、ネットワークの外に出ない特別なアドレス。", "インターネット上のどこかの決まったサーバー会社を指すアドレスではなく、あくまで自分自身を指す。", "同じ社内ネットワークの別のコンピュータではなく、あくまで自分自身のコンピュータを指す。", "空っぽの通信窓口を指す言葉ではなく、自分自身という具体的な宛先を指すアドレス。"], "viz": "<svg viewBox=\"0 0 340 105\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"300\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><text x=\"170\" y=\"45\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自分自身のコンピュータ</text><text x=\"170\" y=\"63\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"normal\">localhost = 127.0.0.1</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ネットワークの外に出ずに、自分自身に通信を送る</text></svg>"}'),

  ('linux-q55', 'ネットワークの基礎',
   '既にプロセスAがポート8080番で通信を待ち受けているところに、別のプロセスBが同じポート8080番で待ち受けようとすると、エラーになることが多い。この理由として最も適切なものはどれか。',
   NULL::text,
   '["1つのポート番号は基本的に1プロセスしか使えず、既に使用中のポートに重ねると衝突する", "ポート番号は一度使うと、コンピュータを再起動するまで永久に消費され尽くしてしまう", "ポート番号は同時に3つのプロセスまでしか登録できないという上限が決まっている", "後から起動したプロセスが自動的に優先され、先発プロセスの通信が乗っ取られる"]',
   0, '[0]', 'single',
   '{"asked": "同じポート番号を2つのプロセスが使おうとするとエラーになる理由を問う問題。", "point": "「1つの窓口は1人しか担当できない」のが基本ルール。既に誰かが使っている受付窓口を、別の人が同時に開こうとすると衝突する。", "kid": "受付窓口が1つしかないのに、2人の担当者が同時にその窓口に座ろうとしているようなもの。先に座っている人がいる以上、もう1人は同じ窓口には座れない。", "eg": "たとえるなら、会議室の予約が1件しか同時に入れられないのに、2つのチームが同じ時間に同じ会議室を予約しようとしているイメージ。先に予約が入っていれば、後から同じ枠を取ろうとすると予約エラーになる。", "terms": [["ポートの衝突", "1つのポート番号を、複数のプロセスが同時に使おうとして起きるエラー"]], "why_asked": "「ポートが使用中です」というエラーメッセージに実際によく出会うが、なぜそうなるかの仕組みを知らないと、原因（別プロセスが既に同じポートを使っている）を追えない。", "think": "なぜ1つの窓口を1つのプロセスしか使えないのかがカギ。もし複数のプロセスが同じポート番号で同時に通信を待ち受けられてしまったら、外部からその番号宛てに届いた通信を、どちらのプロセスに渡せばいいのか決められなくなってしまう。だからOSは、あるポート番号が既に使われている間は、別のプロセスが同じ番号で新しく待ち受けようとするとエラーにして、宛先の取り違えが起きないようにしている。", "vs": "「後から起動した方が乗っ取る」わけではなく、既に使っている側が優先され、後から同じポートを使おうとした側がエラーになる。ポート番号自体が永久に消費されるわけでもない。", "usecase": "自動テストで開発用サーバーを起動しようとしたときに「ポート3000は使用中です」というエラーが出たら、それは既に別のプロセス（前回のテストの残骸など）がそのポートを使い続けていることが原因だと分かる。", "opt": ["正解。1つのポート番号の窓口は基本的に1つのプロセスしか使えず、既に使われているポートに重ねて使おうとすると衝突する。", "ポート番号自体が永久に消費されるわけではなく、そのプロセスが終了すれば再び別のプロセスが使えるようになる。", "3つまでという上限があるわけではなく、同時に使えるのは基本的に1つのプロセスだけという制約。", "後から起動したプロセスが自動的に乗っ取るわけではなく、先に使っている側が優先され、後発側がエラーになる。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"120\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><text x=\"80\" y=\"50\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスA</text><text x=\"80\" y=\"62\" font-size=\"7.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ポート8080使用中</text><rect x=\"180\" y=\"25\" width=\"120\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.2\"/><text x=\"240\" y=\"45\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスB</text><text x=\"240\" y=\"58\" font-size=\"7.5\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">同じ8080番で</text><text x=\"240\" y=\"68\" font-size=\"7.5\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">待ち受けようとする</text><text x=\"150\" y=\"95\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つの窓口を2人は使えない → エラー</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'linux-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
